-- Official CnCRPG adaptation of the SiegeCore C&C wizard. Package CCWizard.
-- GENERATED by cc-conversion/build_official_wizard.py from the SC wizard and
-- dev/ccwiz_official_tail.lua: edit those, not this file.
--
-- The build lives in a Lua table (S) on the machine running the wizard; the
-- character is only written when the player presses Create Character. It
-- reads the game from SiegeCore records in any loaded module:
--   siegepackage (packagetype Race / Class; fields primes, primechoice,
--     attrmods, speed, hitdie, levels.*.{level,xp,bth,hd,spells}, startgold,
--     spellclass, text), item, siegepower (powertype "Wizard 1, Illusionist 1").
-- Hit points use SiegeCore's own level arithmetic (ActionHP.getLevelGain).

local STATS = { "strength", "dexterity", "constitution", "intelligence", "wisdom", "charisma" };
local STAT_SHORT = { strength = "Str", dexterity = "Dex", constitution = "Con", intelligence = "Int", wisdom = "Wis", charisma = "Cha" };
local TABS = { "abilities", "race", "class", "primes", "hp", "equipment", "spells", "finish" };
ALIGNMENTS = { "Lawful Good", "Lawful Neutral", "Lawful Evil", "Neutral Good", "Neutral", "Neutral Evil",
	"Chaotic Good", "Chaotic Neutral", "Chaotic Evil" };

local ROLLTYPE = "ccwiz";
-- Native pixel sizes of the race art (class art is 480 x 600).
PORTRAIT_SIZE = {
	ccwiz_race_human = { 940, 1540 }, ccwiz_race_elf = { 941, 1672 }, ccwiz_race_dwarf = { 941, 1277 },
	ccwiz_race_gnome = { 941, 1269 }, ccwiz_race_halfling = { 941, 1305 }, ccwiz_race_halfelf = { 941, 1672 },
	ccwiz_race_halforc = { 525, 700 },
};
-- Portrait icons this extension ships (graphics_ccwiz.xml).
PORTRAITS = {
	ccwiz_race_human = true, ccwiz_race_dwarf = true, ccwiz_race_elf = true, ccwiz_race_gnome = true,
	ccwiz_race_halfling = true, ccwiz_race_halfelf = true, ccwiz_race_halforc = true,
	ccwiz_class_fighter = true, ccwiz_class_ranger = true, ccwiz_class_rogue = true, ccwiz_class_cleric = true,
	ccwiz_class_druid = true, ccwiz_class_paladin = true, ccwiz_class_bard = true, ccwiz_class_illusionist = true,
	ccwiz_class_wizard = true, ccwiz_class_assassin = true, ccwiz_class_barbarian = true, ccwiz_class_monk = true,
	ccwiz_class_knight = true,
};
local S = {};
local _wMain = nil;
local _rollGeneration = { attr = 0, hp = 0, gold = 0 };
local _pendingAttrs = {};
local _creationPending = false;

function onInit()
	ActionsManager.registerResultHandler(ROLLTYPE, onRoll);
	registerOptions();
	OptionsManager.registerCallback("CCWIZ_LEVEL", onStartingLevelChanged);
	DB.addHandler("ccwizard.blocked.*", "onUpdate", onAvailabilityChanged);
	registerWithBridge();
end

-- Lets the Claude Bridge (a developer tool) test the wizard, when it is loaded.
function registerWithBridge()
	if ClaudeBridge and ClaudeBridge.registerPackage then
		ClaudeBridge.registerPackage("CCWizard", CCWizard);
		-- Test characters get portraits (CampaignDataManager.setCharPortrait).
		ClaudeBridge.registerPackage("CampaignDataManager", CampaignDataManager);
	end
end

function registerOptions()
	local function cycler(sKey, sLabels, sValues, sBaseLabel, sBaseVal, sDefault)
		OptionsManager.registerOptionData({
			sKey = sKey, sGroupRes = "option_header_ccwiz",
			tCustom = { labelsres = sLabels, values = sValues, baselabelres = sBaseLabel, baseval = sBaseVal, default = sDefault },
		});
	end
	local tLevels = {};
	-- C&C classes run to 24th level (2026 Players Handbook tables).
	for n = 2, 24 do table.insert(tLevels, tostring(n)); end
	OptionsManager.registerOptionData({
		sKey = "CCWIZ_LEVEL", sGroupRes = "option_header_ccwiz", sType = "option_entry_cycler",
		tCustom = { labels = table.concat(tLevels, "|"), values = table.concat(tLevels, "|"), baselabel = "1", baseval = "1", default = "1" },
	});
	cycler("CCWIZ_METHOD", "option_val_ccwiz_3d6|option_val_ccwiz_4d6|option_val_ccwiz_3d6order", "3d6|4d6|3d6order",
		"option_val_ccwiz_any", "any", "any");
	cycler("CCWIZ_HP", "option_val_ccwiz_max", "max", "option_val_ccwiz_roll", "roll", "roll");
	cycler("CCWIZ_GOLD", "option_val_ccwiz_max|option_val_ccwiz_x2", "max|x2", "option_val_ccwiz_roll", "roll", "roll");
	OptionsManager.registerOptionData({ sKey = "CCWIZ_REROLL", sGroupRes = "option_header_ccwiz", tCustom = { default = "on" } });
end

--
-- State
--

function reset()
	for s in pairs(_rollGeneration) do
		_rollGeneration[s] = _rollGeneration[s] + 1;
	end
	_pendingAttrs = {};
	S = {
		scores = {}, method = "", race = nil, class = nil, primes = {},
		hp = {}, hptotal = 0, gold = nil, cart = {}, spells = {}, spells2 = {}, spellset = "main",
		combo = { class2 = nil, support = nil, supportclass = nil, plus = {} }, picker = nil,
		manualhp = "", manualbth = "",
		name = "", alignment = "", deity = "", gender = "", age = "", height = "", weight = "",
		appearance = "", notes = "",
	};
end

function getState()
	return S;
end

function getStartLevel()
	local n = tonumber(S.startlevel or OptionsManager.getOption("CCWIZ_LEVEL") or "") or 1;
	return math.max(1, math.min(24, math.floor(n)));
end

function setStartLevel(value)
	local n = tonumber(value);
	if not n or n ~= math.floor(n) or n < 1 or n > 20 then return false; end
	if n == getStartLevel() then return true; end
	S.startlevel = n;
	onStartingLevelChanged(true);
	return true;
end

function onStartingLevelChanged(keepOverride)
	if keepOverride ~= true then S.startlevel = nil; end
	if not _wMain then return; end
	invalidateHP();
	S.manualhp = "";
	S.manualbth = "";
	-- The main list is trimmed to its new slots; a second list (combined
	-- classes) is chosen again.
	local sSet = S.spellset;
	S.spellset = "main";
	local tAllowed = getSpellPicksAllowed();
	S.spellset = sSet;
	S.spells2 = {};
	local tPaths, tCounts = {}, {};
	for sPath in pairs(S.spells) do table.insert(tPaths, sPath); end
	table.sort(tPaths);
	local bRemoved = false;
	for _, sPath in ipairs(tPaths) do
		local nLevel = S.spells[sPath];
		tCounts[nLevel] = (tCounts[nLevel] or 0) + 1;
		if tCounts[nLevel] > (tAllowed[nLevel] or 0) then
			S.spells[sPath] = nil;
			bRemoved = true;
		end
	end
	if bRemoved then ChatManager.SystemMessage(Interface.getString("ccwiz_msg_levelspells")); end
	refreshAll();
end

function canReroll()
	return Session.IsHost or OptionsManager.isOption("CCWIZ_REROLL", "on");
end

--
-- Window and tabs
--

function registerWindow(w)
	registerWithBridge();
	_wMain = w;
	reset();
	S.method = getForcedMethod() or "3d6";
	showTab("abilities");
end

function unregisterWindow(w)
	if _wMain == w then
		_wMain = nil;
	end
end

function getWindow()
	return _wMain;
end

function showTab(sTab)
	local w = _wMain;
	if not w then
		return;
	end
	for _, v in ipairs(TABS) do
		local cSub = w["sub_" .. v];
		if cSub then
			cSub.setVisible(v == sTab);
		end
	end
	S.tab = sTab;
	local cTarget = w["sub_" .. sTab];
	if cTarget and cTarget.subwindow and cTarget.subwindow.onPageShow then
		cTarget.subwindow.onPageShow();
	end
	updateTabs();
end

function refreshPage(sTab)
	local w = _wMain;
	local cSub = w and w["sub_" .. sTab];
	if cSub and cSub.subwindow and cSub.subwindow.onPageShow then
		cSub.subwindow.onPageShow();
	end
end

function isTabDone(sTab)
	if sTab == "abilities" then
		for _, s in ipairs(STATS) do
			if not S.scores[s] then
				return false;
			end
		end
		return true;
	elseif sTab == "race" then
		return S.race ~= nil;
	elseif sTab == "class" then
		return hasPublishedLevel();
	elseif sTab == "primes" then
		local nChosen, nAllowed = getPrimeCounts();
		return S.class ~= nil and S.race ~= nil and nChosen == nAllowed;
	elseif sTab == "hp" then
		if requiresManualProgression() then
			return hasManualProgressionValues();
		end
		return hasSupportedLevel() and countHP() == getStartLevel();
	elseif sTab == "equipment" then
		return S.gold ~= nil;
	elseif sTab == "spells" then
		return (getMainSpellClass() == "" or next(S.spells) ~= nil or not hasMainSpellChoices())
			and (not hasSecondSpells() or next(S.spells2) ~= nil);
	elseif sTab == "finish" then
		return StringManager.trim(S.name or "") ~= "" and StringManager.trim(S.alignment or "") ~= "";
	end
	return false;
end

-- What each step still needs, in plain words (the tab badges and the
-- Finish page's warnings; as the 5e wizard's alerts).
function getTabAlerts(sTab)
	local t = {};
	if sTab == "abilities" then
		if not isTabDone("abilities") then table.insert(t, "Roll the attribute scores"); end
	elseif sTab == "race" then
		if not S.race then table.insert(t, "Choose a race"); end
	elseif sTab == "class" then
		if not S.class then
			table.insert(t, "Choose a class");
		elseif not hasPublishedLevel() then
			table.insert(t, getUnsupportedLevelMessage());
		end
	elseif sTab == "primes" then
		if S.class and S.race and not isTabDone("primes") then
			local nChosen, nAllowed = getPrimeCounts();
			table.insert(t, string.format("Choose primes (%d of %d chosen)", nChosen, nAllowed));
		elseif not (S.class and S.race) then
			table.insert(t, "Choose primes (after race and class)");
		end
	elseif sTab == "hp" then
		if not isTabDone("hp") then
			table.insert(t, requiresManualProgression() and "Enter the hit points and base to hit" or "Roll hit points");
		end
	elseif sTab == "equipment" then
		if not isTabDone("equipment") then table.insert(t, "Roll starting coin"); end
	elseif sTab == "spells" then
		if not isTabDone("spells") then table.insert(t, "Choose spells"); end
	elseif sTab == "finish" then
		for _, s in ipairs(getCreationMissing()) do
			table.insert(t, "Enter " .. s:lower());
		end
	end
	return t;
end

-- Every step's warnings, in tab order (Finish page).
function getAllWarnings()
	local t = {};
	if not Session.IsHost then
		for _, sPath in ipairs({ S.race or "", S.class or "" }) do
			local node = sPath ~= "" and DB.findNode(sPath) or nil;
			if node and isBlocked(DB.getValue(node, "name", "")) then
				table.insert(t, DB.getValue(node, "name", "") .. " is now DM only; choose another");
			end
		end
	end
	for _, v in ipairs(TABS) do
		if v ~= "spells" or getMainSpellClass() ~= "" or hasSecondSpells() then
			for _, s in ipairs(getTabAlerts(v)) do
				table.insert(t, s);
			end
		end
	end
	return t;
end

-- Instructions sections: open or closed on every page together.
local _bInstructions = true;
function getInstructionsShown()
	return _bInstructions;
end
function setInstructionsShown(bShow)
	_bInstructions = bShow and true or false;
	local w = _wMain;
	for _, v in ipairs(TABS) do
		local c = w and w["sub_" .. v];
		local wPage = c and c.subwindow;
		local wInstr = wPage and wPage.sub_instructions and wPage.sub_instructions.subwindow;
		if wInstr and wInstr.update then
			wInstr.update();
		end
	end
end

-- Pick-list filters (Race and Class pages): source module and name.
local _tFilter = { race = { source = "", name = "" }, class = { source = "", name = "" } };
function getFilter(sKind)
	return _tFilter[sKind];
end
function setFilter(sKind, sKey, sValue)
	_tFilter[sKind][sKey] = sValue or "";
	refreshPage(sKind);
end

-- The module a record comes from, by its display name ("Campaign" for campaign records).
function getSourceName(node)
	local sModule = DB.getModule(node);
	if not sModule or sModule == "" then
		return "Campaign";
	end
	local tInfo = Module.getModuleInfo(sModule);
	return (tInfo and tInfo.displayname ~= "" and tInfo.displayname) or sModule;
end

function getSources(sType)
	local t, tSeen = {}, {};
	for _, node in ipairs(getPackages(sType)) do
		local s = getSourceName(node);
		if not tSeen[s] then
			tSeen[s] = true;
			table.insert(t, s);
		end
	end
	table.sort(t);
	return t;
end

-- Opens a race or class record for reading.
function openRecord(sPath)
	Interface.openWindow("siegepackage", sPath);
end

-- Packages for a pick list, after the page's filters.
function getPickList(sType, sKind)
	local tFilter = _tFilter[sKind];
	local sName = (tFilter.name or ""):lower();
	local t = {};
	for _, node in ipairs(getPackages(sType)) do
		if (tFilter.source == "" or getSourceName(node) == tFilter.source)
				and (sName == "" or DB.getValue(node, "name", ""):lower():find(sName, 1, true)) then
			table.insert(t, node);
		end
	end
	return t;
end

function updateTabs()
	local w = _wMain;
	local wTabs = w and w.sub_tabs and w.sub_tabs.subwindow;
	if not wTabs then
		return;
	end
	for _, v in ipairs(TABS) do
		local c = wTabs["tab_" .. v];
		if c then
			c.setFrame(v == S.tab and "buttondown" or "buttonup", 5, 5, 5, 5);
			c.setText(Interface.getString("ccwiz_tab_" .. v));
			-- Badge in the corner (5e wizard): "!" while the step needs something, a check when done.
			local cBadge = c.findWidget("ccwiz_done");
			local sIcon = (#getTabAlerts(v) > 0) and "ccwiz_alert" or "button_dialog_ok_down";
			if cBadge then
				cBadge.setBitmap(sIcon);
			else
				c.addBitmapWidget({ name = "ccwiz_done", icon = sIcon, position = "bottomright", x = -6, y = -6, w = 16, h = 16 });
			end
		end
	end
	local wSpells = wTabs.tab_spells;
	if wSpells then
		wSpells.setVisible(getMainSpellClass() ~= "" or hasSecondSpells());
	end
end

-- Only identity details gate creation; other tabs remain completion reminders.
function isAlignmentValid()
	local sAlign = S.alignment or "";
	if sAlign == "" then return true; end
	for _, s in ipairs((getAllowedAlignments())) do
		if s == sAlign then return true; end
	end
	return false;
end

function getCreationMissing()
 local t = {};
 for _, field in ipairs({ "name", "alignment" }) do
  if StringManager.trim(S[field] or "") == "" then
   table.insert(t, Interface.getString("ccwiz_label_" .. field));
  end
 end
 return t;
end

function getMissing()
	local t = {};
	if not Session.IsHost then
		for _, sPath in ipairs({ S.race or "", S.class or "" }) do
			local node = sPath ~= "" and DB.findNode(sPath) or nil;
			if node and isBlocked(DB.getValue(node, "name", "")) then
				table.insert(t, DB.getValue(node, "name", "") .. " is now DM only; choose another");
			end
		end
	end
	if S.class and not hasSupportedLevel() then
		table.insert(t, getUnsupportedLevelMessage());
	end
	for _, v in ipairs(TABS) do
		if v ~= "finish" and not isTabDone(v) then
			table.insert(t, Interface.getString("ccwiz_tab_" .. v));
		end
	end
	for _, label in ipairs(getCreationMissing()) do
		table.insert(t, label);
	end
	return t;
end

-- Faded full-page art behind a page (as in the other Kraken wizards).
function applyWallpaper(cControl, sIcon)
	if not cControl or not cControl.addBitmapWidget then
		return;
	end
	local cOld = cControl.findWidget and cControl.findWidget("ccwiz_wallpaper");
	if cOld then
		cOld.destroy();
	end
	local nW, nH = 700, 500;
	if cControl.getSize then
		local w, h = cControl.getSize();
		if w and w > 0 then nW = w; end
		if h and h > 0 then nH = h; end
	end
	local nDraw = math.min(nW, nH);
	if nDraw <= 0 then
		nDraw = 500;
	end
	local cWidget = cControl.addBitmapWidget({ name = "ccwiz_wallpaper", icon = sIcon, position = "center", x = 0, y = 0, w = nDraw, h = nDraw });
	if cWidget and cWidget.setColor then
		cWidget.setColor("30FFFFFF");
	end
end

-- Portrait for a race or class, if the extension has one: ccwiz_race_dwarf.
function setPortrait(cControl, sKind, sName)
	if not cControl then
		return;
	end
	-- "Half-Elf (Elven Lineage)" uses the Half-Elf portrait.
	local sIcon = "ccwiz_" .. sKind .. "_" .. (sName or ""):gsub("%s*%b()", ""):lower():gsub("[^a-z]", "");
	local cOld = cControl.findWidget and cControl.findWidget("ccwiz_portrait");
	if cOld then
		cOld.destroy();
	end
	if (sName or "") == "" or not PORTRAITS[sIcon] then
		cControl.setVisible(false);
		return;
	end
	cControl.setVisible(true);
	-- Fit inside the frame keeping the art's shape (0 x 0 before layout = defaults).
	local nW, nH = cControl.getSize();
	if not nW or nW <= 0 then nW = 250; end
	if not nH or nH <= 0 then nH = 330; end
	local tSize = PORTRAIT_SIZE[sIcon] or { 480, 600 };
	local nScale = math.min(nW / tSize[1], nH / tSize[2]);
	cControl.addBitmapWidget({ name = "ccwiz_portrait", icon = sIcon, position = "center", x = 0, y = 0,
		w = math.floor(tSize[1] * nScale), h = math.floor(tSize[2] * nScale) });
end

--
-- Records from every loaded module and the campaign
--

-- The CK can block races and classes (a tick on the Race and Class pages,
-- shown only to the host). Stored in the campaign under ccwizard.blocked,
-- shared with players.
BLOCK_PATH = "ccwizard.blocked";

function blockKey(sName)
	return (sName or ""):lower():gsub("[^a-z0-9]", "");
end

function isBlocked(sName)
	return DB.getValue(BLOCK_PATH .. "." .. blockKey(sName), "", 0) == 1;
end

function setBlocked(sName, bBlocked)
	if not Session.IsHost then
		return;
	end
	local nodeList = DB.createNode(BLOCK_PATH);
	DB.setPublic(DB.createNode("ccwizard"), true);
	DB.setValue(nodeList, blockKey(sName), "number", bBlocked and 1 or 0);
	ChatManager.SystemMessage(string.format(Interface.getString(bBlocked and "ccwiz_allow_blocked" or "ccwiz_allow_enabled"), sName));
	refreshAll();
end

function onAvailabilityChanged()
	if not Session.IsHost then refreshAll(); end
end

function getPackages(sType)
	local t = {};
	local tSeen = {};
	RecordManager.callForEachRecord("siegepackage", function(node)
		if (DB.getValue(node, "packagetype", "")):lower() == sType:lower() then
			local sName = DB.getValue(node, "name", "");
			if sName ~= "" and not tSeen[sName] and (Session.IsHost or not isBlocked(sName)) then
				tSeen[sName] = true;
				table.insert(t, node);
			end
		end
	end);
	table.sort(t, function(a, b) return DB.getValue(a, "name", "") < DB.getValue(b, "name", "") end);
	return t;
end

function getRaceNode()
	return S.race and DB.findNode(S.race);
end

function getClassNode()
	return S.class and DB.findNode(S.class);
end

function selectRace(node)
	local sPath = node and DB.getPath(node) or nil;
	if sPath == S.race then return; end
	S.race = sPath;
	S.primes = {};
	invalidateHP();
	-- Choices follow the race: a class it cannot take goes.
	local nodeClass = getClassNode();
	if nodeClass and getClassBlockReason(nodeClass) then
		selectClass(nil);
		return;
	end
	refreshAll();
end

-- Why a class cannot be chosen with this build, or nil. Race classes are only
-- for their own race (Adventurer's Backpack).
function getClassBlockReason(nodeClass)
	local sClass = nodeClass and DB.getValue(nodeClass, "name", "") or "";
	local sNeed = CCClassRules.getRaceClassRace(sClass);
	if sNeed and not getRaceName():lower():find(sNeed, 1, true) then
		local tPlural = { dwarf = "dwarves", elf = "elves", gnome = "gnomes", halfling = "halflings" };
		return string.format(Interface.getString("ccwiz_reason_raceclass"), tPlural[sNeed] or sNeed);
	end
	return nil;
end

-- Alignments every chosen class allows, and the rule words ("Paladin: Lawful good").
function getAllowedAlignments()
	local tClasses = {};
	local nodeClass = getClassNode();
	if nodeClass then table.insert(tClasses, DB.getValue(nodeClass, "name", "")); end
	local nodeMulti = getMultiNode();
	if nodeMulti then table.insert(tClasses, DB.getValue(nodeMulti, "name", "")); end
	local t, tRules = {}, {};
	for _, sAlign in ipairs(ALIGNMENTS) do
		local bOk = true;
		for _, sClass in ipairs(tClasses) do
			if not CCClassRules.isAlignmentAllowed(sClass, sAlign) then bOk = false; end
		end
		if bOk then table.insert(t, sAlign); end
	end
	for _, sClass in ipairs(tClasses) do
		table.insert(tRules, sClass .. ": " .. CCClassRules.getAlignmentRuleText(sClass));
	end
	return t, table.concat(tRules, "; ");
end

function selectClass(node)
	local sPath = node and DB.getPath(node) or nil;
	if sPath == S.class then return; end
	if node and getClassBlockReason(node) then
		ChatManager.SystemMessage(getClassBlockReason(node));
		return;
	end
	S.class = sPath;
	S.combo = { class2 = nil, support = nil, supportclass = nil, plus = {} };
	S.picker = nil;
	S.spells2 = {};
	S.spellset = "main";
	S.primes = {};
	invalidateHP();
	_rollGeneration.gold = _rollGeneration.gold + 1;
	S.gold = nil;
	S.goldpending = false;
	S.cart = {};
	S.spells = {};
	S.manualhp = "";
	S.manualbth = "";
	refreshAll();
end

function refreshAll()
	updateTabs();
	if S.tab then
		refreshPage(S.tab);
	end
end

-- "+1 Dexterity, -1 Strength"
function describeMods(node)
	local t = {};
	for _, s in ipairs(STATS) do
		local n = DB.getValue(node, "attrmods." .. s, 0);
		if n ~= 0 then
			table.insert(t, string.format("%+d %s", n, StringManager.capitalize(s)));
		end
	end
	if #t == 0 then
		return Interface.getString("ccwiz_label_none");
	end
	return table.concat(t, ", ");
end

function getClassPrime()
	local node = getClassNode();
	if not node then
		return nil;
	end
	for _, s in ipairs(STATS) do
		if DB.getValue(node, "primes." .. s, 0) == 1 then
			return s;
		end
	end
	return nil;
end

--
-- Combining classes at creation (Adventurer's Backpack): multi-class (two
-- classes advancing together), enhanced class (a supporting class or
-- sub-class at half the rate) and class plus (zero-level abilities of more
-- classes, 5% of experience each). The rules are in CCClassRules.
--

function getCombo()
	return S.combo;
end

function getRaceName()
	local node = getRaceNode();
	return node and DB.getValue(node, "name", "") or "";
end

function getClassName()
	local node = getClassNode();
	return node and DB.getValue(node, "name", "") or "";
end

function getHitDie(node)
	return (node and DB.getValue(node, "hitdie", "") or ""):lower():match("(d%d+)") or "";
end

-- The class record a supporting option comes from (Killer -> Assassin).
function findClassRecord(sClassKey)
	for _, node in ipairs(getPackages("Class")) do
		if CCClassRules.key(DB.getValue(node, "name", "")) == sClassKey then
			return node;
		end
	end
	return nil;
end

function getPrimesOf(node)
	local t = {};
	for _, s in ipairs(STATS) do
		if node and DB.getValue(node, "primes." .. s, 0) == 1 then
			table.insert(t, s);
		end
	end
	return t;
end

-- A supporting option's required prime: a sub-class's own, else its class's.
function getSupportPrime(sKey)
	local tSupport = CCClassRules.getSupport(sKey);
	if not tSupport then
		return "";
	end
	if tSupport.prime ~= "" then
		return tSupport.prime;
	end
	return getPrimesOf(findClassRecord(tSupport.class))[1] or "";
end

function getMultiNode()
	return S.combo.class2 and DB.findNode(S.combo.class2);
end

function getSupportClassNode()
	return S.combo.supportclass and DB.findNode(S.combo.supportclass);
end

function getPlusNodes()
	local t = {};
	for sPath in pairs(S.combo.plus) do
		local node = DB.findNode(sPath);
		if node then table.insert(t, node); end
	end
	table.sort(t, function(a, b) return DB.getValue(a, "name", "") < DB.getValue(b, "name", "") end);
	return t;
end

function canCombine()
	local sMain = getClassName();
	if sMain == "" then
		return false, "Choose a class first.";
	end
	if CCClassRules.isRaceClass(sMain) then
		return false, "A race class combines with no other class (Adventurer's Backpack).";
	end
	return true, "";
end

-- Which choice list is open under the class (multi, enhanced, plus), if any.
function getPicker()
	return S.picker;
end

function setPicker(sMode)
	S.picker = (S.picker ~= sMode) and sMode or nil;
	refreshAll();
end

-- Rows for a choice list: { path, key, name, code, rule, allowed, source }
function getComboChoices(sMode)
	local t = {};
	local sMain, sRace = getClassName(), getRaceName();
	local kMain = CCClassRules.key(sMain);
	if sMode == "multi" then
		for _, node in ipairs(getPackages("Class")) do
			local sName = DB.getValue(node, "name", "");
			if CCClassRules.key(sName) ~= kMain then
				local sCode, sRule, bOk = CCClassRules.getMultiRule(sMain, sName, sRace);
				table.insert(t, { path = DB.getPath(node), name = sName, code = sCode, rule = sRule, allowed = bOk, source = getSourceName(node) });
			end
		end
	elseif sMode == "enhanced" then
		for _, o in ipairs(CCClassRules.getSupportOptions()) do
			local nodeClass = findClassRecord(o.class);
			if nodeClass and o.class ~= kMain then
				local sCode, sRule, bOk = CCClassRules.getEnhancedRule(sMain, o.key, sRace);
				local sPrime = getSupportPrime(o.key);
				local sName = o.sub and string.format("%s (%s)", o.name, DB.getValue(nodeClass, "name", "")) or o.name;
				table.insert(t, { path = DB.getPath(nodeClass), key = o.key, name = sName, code = sCode,
					rule = sRule .. (sPrime ~= "" and ("  Needs " .. StringManager.capitalize(sPrime) .. " as a prime.") or ""),
					allowed = bOk, source = getSourceName(nodeClass) });
			end
		end
	elseif sMode == "plus" then
		for _, node in ipairs(getPackages("Class")) do
			local sName = DB.getValue(node, "name", "");
			local sText = CCClassRules.getPlusText(sName);
			if sText and CCClassRules.key(sName) ~= kMain and not CCClassRules.isRaceClass(sName) and not S.combo.plus[DB.getPath(node)] then
				table.insert(t, { path = DB.getPath(node), name = sName, code = "", rule = sText .. ".", allowed = true, source = getSourceName(node) });
			end
		end
	end
	table.sort(t, function(a, b)
		if a.allowed ~= b.allowed then return a.allowed; end
		return a.name < b.name;
	end);
	return t;
end

function chooseCombo(sMode, sPath, sKey)
	if sMode == "multi" then
		S.combo.class2 = sPath;
		S.combo.support, S.combo.supportclass = nil, nil;
	elseif sMode == "enhanced" then
		S.combo.support, S.combo.supportclass = sKey, sPath;
		S.combo.class2 = nil;
	elseif sMode == "plus" then
		S.combo.plus[sPath] = true;
	end
	S.picker = nil;
	S.spells2 = {};
	S.spellset = "main";
	invalidateHP();
	refreshAll();
end

function removeCombo(sMode, sPath)
	if sMode == "multi" then
		S.combo.class2 = nil;
	elseif sMode == "enhanced" then
		S.combo.support, S.combo.supportclass = nil, nil;
	elseif sMode == "plus" then
		S.combo.plus[sPath or ""] = nil;
	end
	S.spells2 = {};
	S.spellset = "main";
	invalidateHP();
	refreshAll();
end

-- Plain words for each chosen combination (Class page, summary).
function describeCombos()
	local t = {};
	local nodeMulti = getMultiNode();
	if nodeMulti then
		local sCode, sRule = CCClassRules.getMultiRule(getClassName(), DB.getValue(nodeMulti, "name", ""), getRaceName());
		table.insert(t, { mode = "multi", path = S.combo.class2, title = "Multi-class: " .. DB.getValue(nodeMulti, "name", ""),
			text = string.format("%s%s Both classes advance together; experience needed is the two classes' added together; hit points use the Multi-Class Hit Die table (%s with %s: %s).",
				sCode ~= "" and ("[" .. sCode .. "] ") or "", sRule, getHitDie(getClassNode()), getHitDie(nodeMulti),
				CCClassRules.getMultiDie({ getHitDie(getClassNode()), getHitDie(nodeMulti) }) or "?") });
	end
	local nodeSupport = getSupportClassNode();
	if nodeSupport and S.combo.support then
		local tSupport = CCClassRules.getSupport(S.combo.support);
		local sCode, sRule = CCClassRules.getEnhancedRule(getClassName(), S.combo.support, getRaceName());
		local nLevel = getStartLevel();
		table.insert(t, { mode = "enhanced", path = S.combo.supportclass,
			title = "Enhanced class, supporting: " .. (tSupport.sub and (tSupport.name .. " (" .. DB.getValue(nodeSupport, "name", "") .. ")") or tSupport.name),
			text = string.format("%s%s Gives: %s. It counts as level %d (half the principal level); at level %d it adds %d XP to each level's experience and gives: %s. Hit points use the Enhanced Class Hit Die table (%s supporting %s: %s).",
				sCode ~= "" and ("[" .. sCode .. "] ") or "", sRule, tSupport.abilities, CCClassRules.getSupportLevel(S.combo.support, nLevel),
				nLevel, CCClassRules.getSupportXP(S.combo.support, nLevel), CCClassRules.getSupportGained(S.combo.support, nLevel),
				getHitDie(nodeSupport), getHitDie(getClassNode()), CCClassRules.getEnhancedDie(getHitDie(nodeSupport), getHitDie(getClassNode())) or "?") });
	end
	for _, node in ipairs(getPlusNodes()) do
		table.insert(t, { mode = "plus", path = DB.getPath(node), title = "Class plus: " .. DB.getValue(node, "name", ""),
			text = (CCClassRules.getPlusText(DB.getValue(node, "name", "")) or "") .. ". Zero level only; costs 5% of all experience earned." });
	end
	return t;
end

-- Primes the build fixes: the class's, a multi-class's, a supporting option's.
function getForcedPrimes()
	local t = {};
	for _, s in ipairs(getPrimesOf(getClassNode())) do t[s] = "from your class"; end
	for _, s in ipairs(getPrimesOf(getMultiNode())) do t[s] = t[s] or "multi-class"; end
	if S.combo.support then
		local s = getSupportPrime(S.combo.support);
		if s ~= "" then t[s] = t[s] or "supporting class"; end
	end
	return t;
end

-- XP a combined character starts with at a level.
function getStartXP(nLevel)
	local nodeClass = getClassNode();
	local nodeRow = nodeClass and getExactLevelRow(nodeClass, nLevel);
	local nXP = nodeRow and DB.getValue(nodeRow, "xp", 0) or 0;
	local nodeMulti = getMultiNode();
	if nodeMulti then
		local nodeRow2 = getExactLevelRow(nodeMulti, nLevel);
		nXP = nXP + (nodeRow2 and DB.getValue(nodeRow2, "xp", 0) or 0);
	end
	if S.combo.support then
		nXP = nXP + CCClassRules.getSupportXP(S.combo.support, nLevel);
	end
	local nPlus = #getPlusNodes();
	if nPlus > 0 then
		nXP = CCClassRules.getPlusXP(nXP, nPlus);
	end
	return nXP;
end

function getLevelRow(node, nLevel)
	local nodeBest, nBest = nil, -1;
	for _, v in pairs(DB.getChildren(node, "levels")) do
		local n = DB.getValue(v, "level", 0);
		if n <= nLevel and n > nBest then
			nodeBest, nBest = v, n;
		end
	end
	return nodeBest;
end

function getExactLevelRow(node, nLevel)
	for _, v in pairs(DB.getChildren(node, "levels")) do
		if DB.getValue(v, "level", 0) == nLevel then
			return v;
		end
	end
	return nil;
end

function hasPublishedLevel()
	local node = getClassNode();
	if not node then return false; end
	for n = 1, getStartLevel() do
		if not getExactLevelRow(node, n) then return false; end
	end
	return true;
end

-- Packages can declare a source-backed XP continuation while explicitly
-- leaving later HP/BtH to the game master.  The wizard never converts the
-- last printed values into a rule: it requires the CK's two numeric inputs.
function requiresManualProgression()
	local node = getClassNode();
	return node and DB.getValue(node, "manualprogression", 0) == 1
		and getStartLevel() >= DB.getValue(node, "manualfromlevel", 0)
		and DB.getValue(node, "manualfromlevel", 0) > 0;
end

local function parseManualNumber(sValue, nMinimum)
	sValue = StringManager.trim(tostring(sValue or ""));
	if not sValue:match("^-?%d+$") then return nil; end
	local n = tonumber(sValue);
	if not n or n < nMinimum then return nil; end
	return n;
end

function getManualProgressionValues()
	if not requiresManualProgression() then return nil, nil; end
	return parseManualNumber(S.manualhp, 1), parseManualNumber(S.manualbth, -9999);
end

function hasManualProgressionValues()
	if not requiresManualProgression() then return true; end
	local nHP, nBtH = getManualProgressionValues();
	return nHP ~= nil and nBtH ~= nil;
end

function getSelectedHPTotal()
	local nHP = select(1, getManualProgressionValues());
	return nHP or S.hptotal or 0;
end

function setManualProgressionValues(sHP, sBtH)
	S.manualhp = tostring(sHP or "");
	S.manualbth = tostring(sBtH or "");
	refreshAll();
end

function hasSupportedLevel()
	return hasPublishedLevel() and hasManualProgressionValues();
end

function getUnsupportedLevelMessage()
	-- The level is published but its HP and BtH are the Castle Keeper's: say so,
	-- also once they are entered (the note stays on the Hit Points page).
	if hasPublishedLevel() and requiresManualProgression() then
		return string.format(Interface.getString("ccwiz_msg_manualprogression"), getStartLevel());
	end
	return string.format(Interface.getString("ccwiz_msg_unsupportedlevel"), getStartLevel());
end

-- Abilities a package grants up to a level: { {name, level} }
function getAbilitiesUpTo(node, nLevel)
	local t = {};
	for _, v in pairs(DB.getChildren(node, "abilities")) do
		local n = tonumber(DB.getValue(v, "level", 1)) or 1;
		if n <= nLevel then
			table.insert(t, { name = DB.getValue(v, "name", ""), level = n });
		end
	end
	table.sort(t, function(a, b) if a.level ~= b.level then return a.level < b.level end return a.name < b.name end);
	return t;
end

--
-- Attributes
--

function getForcedMethod()
	local s = OptionsManager.getOption("CCWIZ_METHOD") or "any";
	if s == "" or s == "any" then
		return nil;
	end
	return s;
end

function setMethod(s)
	if getForcedMethod() then
		return;
	end
	S.method = s;
end

function getMethod()
	return getForcedMethod() or S.method or "3d6";
end

function getModifier(nScore)
	local n = nScore or 10; if n <= 3 then return -3; elseif n <= 5 then return -2; elseif n <= 8 then return -1; elseif n <= 12 then return 0; elseif n <= 15 then return 1; elseif n <= 17 then return 2; else return 3; end
end

function getRaceMod(sStat)
	local node = getRaceNode();
	return node and DB.getValue(node, "attrmods." .. sStat, 0) or 0;
end

function getFinalScore(sStat)
	if not S.scores[sStat] then
		return nil;
	end
	return S.scores[sStat] + getRaceMod(sStat);
end

function rollAll()
	if (next(S.scores) or next(_pendingAttrs)) and not canReroll() then
		return;
	end
	_rollGeneration.attr = _rollGeneration.attr + 1;
	_pendingAttrs = {};
	S.scores = {};
	invalidateHP();
	for _, s in ipairs(STATS) do
		rollAttribute(s);
	end
end

function rollAttribute(sStat)
	if _pendingAttrs[sStat] or (S.scores[sStat] and not canReroll()) then return; end
	_pendingAttrs[sStat] = true;
	local sMethod = getMethod();
	local tDice = { "d6", "d6", "d6" };
	if sMethod == "4d6" then
		tDice = { "d6", "d6", "d6", "d6" };
	end
	performRoll(tDice, 0, "attr", sStat, StringManager.capitalize(sStat) .. " (" .. (sMethod == "4d6" and "4d6 drop lowest" or "3d6") .. ")");
end

function swapScores(sA, sB)
	if sA == sB or getMethod() == "3d6order" then
		return;
	end
	S.scores[sA], S.scores[sB] = S.scores[sB], S.scores[sA];
	invalidateHP();
	refreshAll();
end

--
-- Rolls (shown in chat, handled here)
--

function performRoll(tDice, nMod, sPurpose, sArg, sDesc)
	local rActor = nil;
	local rRoll = {
		sType = ROLLTYPE,
		sDesc = string.format(Interface.getString("ccwiz_msg_rolled"), sDesc),
		aDice = tDice,
		nMod = nMod or 0,
		sPurpose = sPurpose,
		sArg = sArg or "",
		nWizardGeneration = _rollGeneration[sPurpose],
		sHPSignature = sPurpose == "hp" and getHPSignature() or nil,
	};
	ActionsManager.performAction(nil, rActor, rRoll);
end

function onRoll(rSource, rTarget, rRoll)
	if rRoll.nWizardGeneration and tonumber(rRoll.nWizardGeneration) ~= _rollGeneration[rRoll.sPurpose] then
		return;
	end
	if rRoll.sPurpose == "hp" and rRoll.sHPSignature and rRoll.sHPSignature ~= getHPSignature() then
		invalidateHP();
		refreshAll();
		return;
	end
	local tValues = {};
	for _, v in ipairs(rRoll.aDice or {}) do
		table.insert(tValues, v.result or 0);
	end
	local nTotal = 0;
	if rRoll.sPurpose == "attr" and #tValues == 4 then
		local nLowest = 1;
		for i = 2, 4 do
			if tValues[i] < tValues[nLowest] then nLowest = i; end
		end
		table.sort(tValues);
		rRoll.aDice[nLowest].dropped = true;
		for i = 2, 4 do
			nTotal = nTotal + tValues[i];
		end
		rRoll.sDesc = rRoll.sDesc .. " [dropped " .. tValues[1] .. "]";
	else
		for _, n in ipairs(tValues) do
			nTotal = nTotal + n;
		end
	end
	nTotal = nTotal + (tonumber(rRoll.nMod) or 0);

	if rRoll.sPurpose == "attr" then
		_pendingAttrs[rRoll.sArg] = nil;
		S.scores[rRoll.sArg] = nTotal;
		invalidateHP();
	elseif rRoll.sPurpose == "hp" then
		local nLevel = tonumber(rRoll.sArg) or 1;
		S.hp[nLevel] = true and math.max(1, nTotal) or nTotal;
		S.hpsignature = getHPSignature();
		S.hptotal = 0;
		for _, n in pairs(S.hp) do
			S.hptotal = S.hptotal + n;
		end
		if countHP() == getStartLevel() then S.hppending = false; end
	elseif rRoll.sPurpose == "gold" then
		S.goldpending = false;
		local nMult = tonumber(rRoll.sArg) or 1;
		S.gold = nTotal * nMult;
		rRoll.sDesc = rRoll.sDesc .. string.format(" [x%d = %d gp]", nMult, S.gold);
	end

	local rMessage = ActionsManager.createActionMessage(rSource, rRoll);
	-- Rolled for a character that does not exist yet: show who rolled, not the
	-- identity the player last used.
	rMessage.sender = Session.IsHost and Interface.getString("ccwiz_sender_gm") or (User.getUsername() or "");
	rMessage.icon = nil;
	Comm.deliverChatMessage(rMessage);
	refreshAll();
end

--
-- Primes
--

function getPrimeCounts()
	local nAllowed = 0;
	local nodeRace, nodeClass = getRaceNode(), getClassNode();
	if nodeClass then
		for _, s in ipairs(STATS) do
			nAllowed = nAllowed + DB.getValue(nodeClass, "primes." .. s, 0);
		end
		nAllowed = nAllowed + DB.getValue(nodeClass, "primechoice", 0);
	end
	if nodeRace then
		nAllowed = nAllowed + DB.getValue(nodeRace, "primechoice", 0);
	end
	-- A multi-class character also has the second class's prime.
	nAllowed = nAllowed + #getPrimesOf(getMultiNode());
	local nChosen = 0;
	local tForced = getForcedPrimes();
	for _, s in ipairs(STATS) do
		if tForced[s] or S.primes[s] then
			nChosen = nChosen + 1;
		end
	end
	return nChosen, nAllowed;
end

function isForcedPrime(sStat)
	return getForcedPrimes()[sStat];
end

function togglePrime(sStat, bOn)
	if getForcedPrimes()[sStat] then
		return;
	end
	if bOn then
		local nChosen, nAllowed = getPrimeCounts();
		if nChosen >= nAllowed then
			ChatManager.SystemMessage(string.format(Interface.getString("ccwiz_msg_primelimit"), nAllowed));
			refreshAll();
			return;
		end
	end
	S.primes[sStat] = bOn or nil;
	refreshAll();
end

--
-- Hit points
--

-- Levels still to roll, and the dice for each: { {level, dice, flat} }
function getHPPlan()
	local node = getClassNode();
	if not node or not hasPublishedLevel() or requiresManualProgression() then
		return {};
	end
	local t = {};
	local sDie = getComboDie();
	for n = 1, getStartLevel() do
		local tDice, nFlat = getOfficialHPGain(node, n);
		if sDie then
			for i = 1, #tDice do tDice[i] = sDie; end
		end
		table.insert(t, { level = n, dice = tDice, flat = nFlat });
	end
	return t;
end

-- The hit die of a combined character (Adventurer's Backpack tables), or nil.
function getComboDie()
	local sMain = getHitDie(getClassNode());
	local nodeMulti = getMultiNode();
	if nodeMulti then
		return CCClassRules.getMultiDie({ sMain, getHitDie(nodeMulti) });
	end
	local nodeSupport = getSupportClassNode();
	if nodeSupport and S.combo.support then
		return CCClassRules.getEnhancedDie(getHitDie(nodeSupport), sMain);
	end
	return nil;
end

function countHP()
	if S.hpsignature and S.hpsignature ~= getHPSignature() then invalidateHP(); end
	local n = 0;
	for _ in pairs(S.hp) do
		n = n + 1;
	end
	return n;
end

function invalidateHP()
	if next(S.hp or {}) then S.hpnotice = Interface.getString("ccwiz_msg_hpreset"); end
	_rollGeneration.hp = _rollGeneration.hp + 1;
	S.hp = {};
	S.hptotal = 0;
	S.hpsignature = nil;
	S.hppending = false;
end

function getHPSignature()
	return table.concat({ S.class or "", S.race or "", tostring(getStartLevel()), tostring(getConMod()),
		S.combo.class2 or "", S.combo.support or "",
		OptionsManager.getOption("CCWIZ_HP") or "", OptionsManager.getOption("SIEGE_HP_CON") or "",
		OptionsManager.getOption("SIEGE_HP_MIN1") or "" }, "|");
end

function getConMod()
	return getModifier(getFinalScore("constitution") or 10);
end

function rollHP()
	if not getClassNode() then
		ChatManager.SystemMessage(Interface.getString("ccwiz_msg_noclass"));
		return;
	end
	if not hasPublishedLevel() or requiresManualProgression() then
		ChatManager.SystemMessage(getUnsupportedLevelMessage());
		return;
	end
	if (countHP() > 0 or S.hppending) and not canReroll() then
		return;
	end
	invalidateHP();
	S.hpnotice = nil;
	S.hpsignature = getHPSignature();
	S.hppending = true;
	local nCon = getConMod();
	for _, r in ipairs(getHPPlan()) do
		if #r.dice == 0 then
			S.hp[r.level] = r.flat;
			S.hptotal = S.hptotal + r.flat;
		elseif r.level == 1 and OptionsManager.isOption("CCWIZ_HP", "max") then
			local nMax = r.flat + (true and nCon or 0);
			for _, d in ipairs(r.dice) do
				nMax = nMax + (tonumber(d:match("d(%d+)")) or 0);
			end
			S.hp[1] = true and math.max(1, nMax) or nMax;
			S.hptotal = S.hptotal + S.hp[1];
		else
			local nMod = r.flat + (true and nCon or 0);
			performRoll(r.dice, nMod, "hp", tostring(r.level),
				string.format("%s %s %d", Interface.getString("ccwiz_tab_hp"), DB.getValue(getClassNode(), "name", ""), r.level));
		end
	end
	if countHP() == getStartLevel() then S.hppending = false; end
	refreshAll();
end

--
-- Coin and shopping (all sums in copper)
--

-- Price in copper, or nil when the price is not one plain amount ("1,000-25,000*",
-- "see table 3.6", "*"): such items cannot be bought in the shop.
function parseCost(s)
	s = StringManager.trim((s or ""):lower():gsub(",", ""));
	local n, sUnit = s:match("^([%d%.]+)%s*(%a%a)$");
	n = tonumber(n);
	if not n then
		return nil;
	end
	local tMult = { pp = 1000, gp = 100, ep = 50, sp = 10, cp = 1 };
	return math.floor(n * (tMult[sUnit] or 100) + 0.5);
end

function formatCopper(n)
	n = math.floor(n or 0);
	local nGP = math.floor(n / 100);
	local nSP = math.floor((n % 100) / 10);
	local nCP = n % 10;
	local t = {};
	if nGP > 0 then table.insert(t, nGP .. " gp"); end
	if nSP > 0 then table.insert(t, nSP .. " sp"); end
	if nCP > 0 or #t == 0 then table.insert(t, nCP .. " cp"); end
	return table.concat(t, " ");
end

function rollGold()
	local node = getClassNode();
	if not node then
		ChatManager.SystemMessage(Interface.getString("ccwiz_msg_noclass"));
		return;
	end
	if (S.gold ~= nil or S.goldpending) and not canReroll() then
		return;
	end
	_rollGeneration.gold = _rollGeneration.gold + 1;
	S.goldpending = false;
	local sGold = DB.getValue(node, "startgold", "");
	local sDice, sMult = sGold:match("^(%d*d%d+)x?(%d*)$");
	if not sDice then
		ChatManager.SystemMessage(Interface.getString("ccwiz_msg_nogold"));
		S.gold = 0;
		refreshAll();
		return;
	end
	local nMult = tonumber(sMult) or 1;
	local tDice = DiceManager.convertStringToDice(sDice);
	if #S.cart > 0 then
		ChatManager.SystemMessage(Interface.getString("ccwiz_msg_cartreturned"));
	end
	S.cart = {};
	if OptionsManager.isOption("CCWIZ_GOLD", "max") then
		local n = 0;
		for _, d in ipairs(tDice) do
			n = n + (tonumber((type(d) == "table" and d.type or d):match("d(%d+)")) or 0);
		end
		S.gold = n * nMult;
		refreshAll();
		return;
	end
	if OptionsManager.isOption("CCWIZ_GOLD", "x2") then
		nMult = nMult * 2;
	end
	S.goldpending = true;
	performRoll(tDice, 0, "gold", tostring(nMult), Interface.getString("ccwiz_label_gold") .. " " .. sGold);
end

function getSpent()
	local n = 0;
	for _, v in ipairs(S.cart) do
		n = n + v.cost * v.count;
	end
	return n;
end

function getLeft()
	return (S.gold or 0) * 100 - getSpent();
end

function buy(node)
	if not node then
		return;
	end
	if not S.gold then
		ChatManager.SystemMessage(Interface.getString("ccwiz_msg_rollcoinfirst"));
		return;
	end
	local nCost = parseCost(DB.getValue(node, "cost", ""));
	if not nCost or nCost > getLeft() then
		ChatManager.SystemMessage(string.format(Interface.getString("ccwiz_msg_poor"), DB.getValue(node, "name", "")));
		return;
	end
	local sPath = DB.getPath(node);
	for _, v in ipairs(S.cart) do
		if v.path == sPath then
			v.count = v.count + 1;
			refreshAll();
			return;
		end
	end
	table.insert(S.cart, { path = sPath, name = DB.getValue(node, "name", ""), cost = nCost, count = 1 });
	refreshAll();
end

function unbuy(sPath)
	for i, v in ipairs(S.cart) do
		if v.path == sPath then
			v.count = v.count - 1;
			if v.count <= 0 then
				table.remove(S.cart, i);
			end
			break;
		end
	end
	refreshAll();
end

-- Shop category of an item record.
function getItemCategory(node)
	local sType = DB.getValue(node, "type", ""):lower();
	local sSub = DB.getValue(node, "subtype", ""):lower();
	if sType == "weapon" then return "weapon"; end
	if sType == "armor" or sSub == "shield" or sSub == "helm" then return "armor"; end
	if sSub == "clothing" then return "clothing"; end
	if sSub == "provisions" then return "provisions"; end
	if sSub == "transport" then return "transport"; end
	return "gear";
end

-- Gear the class can use: the WEAPONS and ARMOR lines of its class text
-- (the shop compares names by their words, so "greek ensemble" is "Ensemble,
-- Greek" and "hand axe" is "Axe, Hand/Throw"), shields and helms by the Class
-- Reference Table. The shop leaves out the rest (no plate mail for a wizard).
-- A class whose text has no such lines (a race class) is not limited.
local USE_SYN = { quarterstaff = "staff", longsword = "long sword", broadsword = "broad sword",
	shortsword = "short sword", chainmail = "mail", chain = "mail", bouilli = "bouille", breastplates = "breastplate" };
local USE_DROP = { ["and"] = true, ["the"] = true, ["of"] = true, ["see"] = true, ["armor"] = true, ["a"] = true,
	["an"] = true };
-- Words an armor may add to a class's entry ("Breastplate, bronze" for
-- "breastplates", "Mail Shirt" for "shirt").
local USE_ARMOR_EXTRA = { bronze = true, steel = true, mail = true };
-- Words that make another weapon ("Club, Heavy" is not "club").
local USE_WEAPON_VARIANT = { heavy = true, great = true, large = true, two = true, handed = true };
local USE_POLEARMS = { ["bardiche"] = true, ["bec de corbin"] = true, ["bill or billhook"] = true, ["fauchard"] = true,
	["fauchard fork"] = true, ["glaive"] = true, ["guisarme"] = true, ["halberd"] = true, ["lucerne hammer"] = true,
	["partisan"] = true, ["pike"] = true, ["ranseur"] = true, ["voulge"] = true, ["fork, military"] = true };
-- Class Reference Table: Armor, Shields, Helms (classes not listed: any).
local USE_SHIELD_HELM = {
	["Assassin"] = { { "small", "buckler", "pavis" }, { "coif, leather" } },
	["Bard"] = { { "small", "buckler", "medium" },
		{ "bacinet", "casquet", "coif, chain", "coif, leather", "helm, normal", "helm, pot", "war hat" } },
	["Druid"] = { { "wooden" }, { "coif, leather" } },
	["Illusionist"] = { {}, {} },
	["Monk"] = { {}, {} },
	["Wizard"] = { {}, {} },
	["Ranger"] = { { "small", "buckler", "medium", "pavis" },
		{ "benin", "casquet", "coif, chain", "coif, leather", "helm, norman", "helm, pot", "war hat" } },
	["Rogue"] = { { "small", "buckler", "medium", "pavis" }, { "coif, leather", "war hat" } },
};

local function useWords(s)
	local t = {};
	s = (s or ""):lower():gsub("[%-/]", " ");
	for w in s:gmatch("%a+") do
		w = USE_SYN[w] or w;
		for x in w:gmatch("%a+") do
			if not USE_DROP[x] then
				if #x > 3 and x:sub(-1) == "s" and x:sub(-2) ~= "ss" then
					x = x:sub(1, -2);
				end
				t[x] = true;
			end
		end
	end
	return t;
end

local function useSubset(a, b)
	for k in pairs(a) do
		if not b[k] then return false; end
	end
	return next(a) ~= nil;
end

local function useTokens(sLine)
	local t = {};
	local s = (sLine or ""):gsub("&", ","):gsub("%f[%a][Aa]nd%f[%A]", ",");
	for sTok in s:gmatch("[^,]+") do
		local sAny = sTok:lower():find("%(any%)") ~= nil;
		sTok = StringManager.trim(sTok:gsub("%b()", "")):lower();
		local bOr = sTok:find(" or ", 1, true) ~= nil;
		if bOr then
			sTok = sTok:gsub("%f[%a]light%f[%A]", ""):gsub("%f[%a]heavy%f[%A]", ""):gsub("%f[%a]or%f[%A]", "");
		end
		if sTok ~= "" and sTok ~= "special" then
			table.insert(t, { words = useWords(sTok), text = sTok, wide = sAny or bOr });
		end
	end
	return t;
end

local function useAllowed(sLine, sName, bArmor)
	local l = StringManager.trim(sLine or ""):lower();
	if l:find("^any") then return true; end
	if l == "" or l:find("^none") then return false; end
	local sLower = sName:lower();
	local tItem = useWords(sName);
	for _, tok in ipairs(useTokens(sLine)) do
		if tok.text:find("^polearm") and USE_POLEARMS[sLower] then
			return true;
		end
		local T = tok.words;
		if next(T) then
			if bArmor then
				if useSubset(T, tItem) then
					local bOk = true;
					for k in pairs(tItem) do
						if not T[k] and not USE_ARMOR_EXTRA[k] then bOk = false; end
					end
					if bOk then return true; end
				end
			elseif not USE_POLEARMS[sLower] or (useSubset(T, tItem) and useSubset(tItem, T)) then
				if useSubset(T, tItem) then
					local bOk = true;
					if not tok.wide then
						for k in pairs(tItem) do
							if not T[k] and USE_WEAPON_VARIANT[k] then bOk = false; end
						end
					end
					if bOk then return true; end
				end
				if useSubset(tItem, T) then
					return true;
				end
			end
		end
	end
	return false;
end

local _tUseLines = {};
local function getUseLines(nodeClass)
	local sPath = DB.getPath(nodeClass);
	if _tUseLines[sPath] then
		return _tUseLines[sPath];
	end
	local s = DB.getValue(nodeClass, "text", "") or "";
	s = s:gsub("<[^>]+>", " "):gsub("&#%d+;", " "):gsub("&amp;", "&");
	local t = { weapons = s:match("WEAPONS[%u ]*:%s*(.-)%s*ARMOR"), armor = s:match("ARMOR[%u ]*:%s*(.-)%s*ABILITIES") };
	_tUseLines[sPath] = t;
	return t;
end

local function isUsableByOneClass(nodeClass, node)
	local tLines = getUseLines(nodeClass);
	local sName = DB.getValue(node, "name", "");
	local sType = DB.getValue(node, "type", ""):lower();
	local sSub = DB.getValue(node, "subtype", ""):lower();
	local sClass = DB.getValue(nodeClass, "name", "");
	if sSub == "shield" or sSub == "helm" then
		local tSH = USE_SHIELD_HELM[sClass];
		if not tSH then return true; end
		local sLower = sName:lower();
		for _, k in ipairs(sSub == "shield" and tSH[1] or tSH[2]) do
			if sLower:find(k, 1, true) then return true; end
		end
		return false;
	end
	if sType == "armor" then
		return not tLines.armor or useAllowed(tLines.armor, sName, true);
	end
	if sType == "weapon" then
		if not tLines.weapons then return true; end
		local sLower = sName:lower();
		-- Ammunition follows its launcher.
		if sLower:find("arrow", 1, true) then
			return useAllowed(tLines.weapons, "Bow, Long") or useAllowed(tLines.weapons, "Bow, Short");
		end
		if sLower:find("bolt", 1, true) then
			return useAllowed(tLines.weapons, "Crossbow, Light") or useAllowed(tLines.weapons, "Crossbow, Hand")
				or useAllowed(tLines.weapons, "Crossbow, Heavy");
		end
		return useAllowed(tLines.weapons, sName);
	end
	return true;
end

-- True if the chosen class (or a multi-class second class) can use the item.
function isUsableByClass(node)
	local nodeClass = getClassNode();
	if not nodeClass then
		return true;
	end
	if isUsableByOneClass(nodeClass, node) then
		return true;
	end
	local nodeMulti = getMultiNode and getMultiNode();
	return nodeMulti ~= nil and isUsableByOneClass(nodeMulti, node);
end

-- Shop order: armor, weapons, then the rest.
local SHOP_ORDER = { armor = 1, weapon = 2, gear = 3, clothing = 4, provisions = 5, transport = 6 };

-- Item types that are found, not bought.
NOT_FOR_SALE = { treasure = true, magic = true };

-- What the shop offers: nothing until the starting coin is rolled; then every
-- item with a plain price the character can still afford, except treasure
-- and magic items.
-- When two books sell the same item (the Adventurer's Backpack repeats PHB
-- gear, sometimes with other figures), the Player's Handbook copy is the one sold.
local CORE_BOOK = "@C&C Player's Handbook";
local function isCore(node) return DB.getPath(node):sub(-#CORE_BOOK) == CORE_BOOK; end

function getShopItems(sCategory, sSearch)
	local t = {};
	local tByName = {};
	if not S.gold then
		return t;
	end
	local nLeft = getLeft();
	sSearch = (sSearch or ""):lower();
	forEachOfficial("items", function(node)
		local sName = DB.getValue(node, "name", "");
		if sName == "" or NOT_FOR_SALE[DB.getValue(node, "type", ""):lower()] then
			return;
		end
		if tByName[sName] and (isCore(tByName[sName]) or not isCore(node)) then
			return;
		end
		local nCost = parseCost(DB.getValue(node, "cost", ""));
		if not nCost or nCost > nLeft then
			return;
		end
		if (sCategory or "all") ~= "all" and getItemCategory(node) ~= sCategory then
			return;
		end
		if not isUsableByClass(node) then
			return;
		end
		-- Magic items are found, not bought ("Leather Armor, +1", templates).
		if sName:find("[%+%-]%s*%d") or sName:find("%(Template%)") then
			return;
		end
		if sSearch ~= "" and not sName:lower():find(sSearch, 1, true) then
			return;
		end
		tByName[sName] = node;
	end);
	for _, node in pairs(tByName) do
		table.insert(t, node);
	end
	table.sort(t, function(a, b)
		local na, nb = SHOP_ORDER[getItemCategory(a)] or 9, SHOP_ORDER[getItemCategory(b)] or 9;
		if na ~= nb then return na < nb; end
		return DB.getValue(a, "name", "") < DB.getValue(b, "name", "");
	end);
	return t;
end

--
-- Spells
--

-- A combined character can have a second spell list: a multi-class
-- caster's, or a spell-casting supporting class's (its Supporting Spells
-- table). The Spells page switches between them ("main" / "second").
-- A spell class with nothing to pick from its lists (a divine knight casts
-- with mana, a magic user channels siege points) does not hold up the step.
function hasMainSpellChoices()
	local sSet = S.spellset;
	S.spellset = "main";
	local bAny = #getSpellChoices("") > 0;
	S.spellset = sSet;
	return bAny;
end

function getMainSpellClass()
	local node = getClassNode();
	return node and DB.getValue(node, "spellclass", "") or "";
end

function getSecondSpellClass()
	local nodeMulti = getMultiNode();
	if nodeMulti then
		return DB.getValue(nodeMulti, "spellclass", "");
	end
	if S.combo.support and CCClassRules.getSupportSlots(S.combo.support, getStartLevel()) then
		local nodeSupport = getSupportClassNode();
		return nodeSupport and DB.getValue(nodeSupport, "spellclass", "") or "";
	end
	return "";
end

function hasSecondSpells()
	return getSecondSpellClass() ~= "";
end

function getSpellSet()
	if S.spellset == "second" and hasSecondSpells() then
		return "second";
	end
	return "main";
end

function setSpellSet(s)
	S.spellset = s;
	refreshAll();
end

-- The picks of the list being shown: { [path] = spell level }.
function getSpellPicks()
	return getSpellSet() == "second" and S.spells2 or S.spells;
end

function getSpellClass()
	if getSpellSet() == "second" then
		return getSecondSpellClass();
	end
	return getMainSpellClass();
end

-- Spells per day at the starting level: { [0]=4, [1]=2, ... }
function getSpellsPerDay()
	local t = {};
	if getSpellSet() == "second" then
		if S.combo.support then
			return CCClassRules.getSupportSlots(S.combo.support, getStartLevel()) or t;
		end
		return getSlotsFor(getMultiNode(), getStartLevel());
	end
	local node = getClassNode();
	if not node or not hasPublishedLevel() then
		return t;
	end
	return getSlotsFor(node, getStartLevel());
end

-- How many spells may be picked per level: the spells per day, or for a class
-- that casts the spells it knows (package spellmode "known") its level row's
-- known counts ("3,2" = three 0-level, two 1st-level).
function getSpellPicksAllowed()
	if getSpellSet() ~= "second" then
		local node = getClassNode();
		if node and hasPublishedLevel() and DB.getValue(node, "spellmode", ""):lower() == "known" then
			local nodeRow = getLevelRow(node, getStartLevel());
			local sKnown = nodeRow and DB.getValue(nodeRow, "known", "") or "";
			if sKnown ~= "" then
				local t, i = {}, 0;
				for sCount in sKnown:gmatch("[^,]+") do
					t[i] = tonumber(sCount) or 0;
					i = i + 1;
				end
				return t;
			end
		end
	end
	return getSpellsPerDay();
end

function getSlotsFor(node, nLevel)
	local t = {};
	if not node then
		return t;
	end
	local nodeRow = getLevelRow(node, nLevel);
	local s = nodeRow and DB.getValue(nodeRow, "slots", "") or "";
	local i = 0;
	for sCount in s:gmatch("[^,]+") do
		t[i] = tonumber(sCount) or 0;
		i = i + 1;
	end
	-- Game packages may opt into score-based bonus slots without making the
	-- wizard know any game-specific class names or thresholds.  The helper
	-- returns a cloned table, so the package row and its static values remain
	-- untouched while the preview reflects the race-adjusted casting score.
	local sBonusStat = DB.getValue(node, "slotbonusstat", "");
	local sBonusRules = DB.getValue(node, "slotbonuses", "");
	if sBonusStat ~= "" and sBonusRules ~= "" and SiegeChar and SiegeChar.applySlotBonuses then
		t = SiegeChar.applySlotBonuses(t, getFinalScore(sBonusStat) or 10, sBonusRules);
	end
	return t;
end

function getMaxSpellLevel()
	local nMax = -1;
	for n, nCount in pairs(getSpellsPerDay()) do
		if nCount > 0 and n > nMax then
			nMax = n;
		end
	end
	return nMax;
end

-- Level of a power for a class, from powertype "Wizard 1, Illusionist 1".
function getPowerLevelFor(node, sClass)
	local sType = DB.getValue(node, "powertype", "");
	for sName, sLevel in sType:gmatch("([%a%s]+)%s+(%d+)") do
		if StringManager.trim(sName):lower() == sClass:lower() then
			return tonumber(sLevel);
		end
	end
	return nil;
end

function getSpellChoices(sSearch, nOnlyLevel)
	local sClass = getSpellClass();
	local nMax = getMaxSpellLevel();
	local t = {};
	local tSeen = {};
	if sClass == "" or nMax < 0 then
		return t;
	end
	sSearch = (sSearch or ""):lower();
	forEachOfficial("spells", function(node)
		local sName = DB.getValue(node, "name", "");
		local nLevel = getPowerLevelFor(node, sClass);
		if nLevel and nLevel <= nMax and (not nOnlyLevel or nLevel == nOnlyLevel)
				and not tSeen[sName] and (sSearch == "" or sName:lower():find(sSearch, 1, true)) then
			tSeen[sName] = true;
			table.insert(t, { node = node, level = nLevel });
		end
	end);
	table.sort(t, function(a, b) if a.level ~= b.level then return a.level < b.level end
		return DB.getValue(a.node, "name", "") < DB.getValue(b.node, "name", "") end);
	return t;
end

function toggleSpell(sPath, bOn)
	-- S.spells[path] = the spell's level for this class. Picks per level are
	-- limited to the spells per day at that level.
	if bOn then
		local nLevel = getPowerLevelFor(DB.findNode(sPath), getSpellClass()) or 0;
		local nAllowed = getSpellPicksAllowed()[nLevel] or 0;
		if not getSpellPicks()[sPath] and countSpellsAt(nLevel) >= nAllowed then
			ChatManager.SystemMessage(string.format(Interface.getString("ccwiz_msg_spellfull"),
				nLevel == 0 and Interface.getString("ccwiz_spells_level0") or string.format(Interface.getString("ccwiz_spells_leveln"), nLevel), nAllowed));
			return false;
		end
		getSpellPicks()[sPath] = nLevel;
	else
		getSpellPicks()[sPath] = nil;
	end
	updateTabs();
end

function countSpellsAt(nLevel)
	local n = 0;
	for _, v in pairs(getSpellPicks()) do
		if v == nLevel then
			n = n + 1;
		end
	end
	return n;
end

-- A plain-language row per spell level, also reporting how many picks remain.
function describeSpellPicks()
	local t = {};
	local tDay = getSpellPicksAllowed();
	for i = 0, 9 do
		local nAllowed = tDay[i] or 0;
		if nAllowed > 0 then
			local nChosen = countSpellsAt(i);
			table.insert(t, string.format(Interface.getString("ccwiz_spells_pickrow"), i,
				nChosen, nAllowed, math.max(0, nAllowed - nChosen)));
		end
	end
	return table.concat(t, "\n"), #t;
end

function countSpells()
	local n = 0;
	for _ in pairs(S.spells) do
		n = n + 1;
	end
	for _ in pairs(S.spells2) do
		n = n + 1;
	end
	return n;
end

--
-- Create the character
--

function createCharacter()
	if _creationPending then return; end
	-- Nothing blocks creation (Mike, 2026-10-14: a player can make a character
	-- without the CK and finish the choices with them later). What is still
	-- open goes into the sheet's notes and the chat.
	S.unfinished = getMissing();
	if StringManager.trim(S.name or "") == "" then
		S.name = Interface.getString("ccwiz_unnamed");
	end
	local nStartingLevel = getStartLevel();
	if Session.IsHost then
		local nodeChar = DB.createChild("charsheet");
		DB.setValue(nodeChar, "name", "string", StringManager.trim(S.name));
		RecordManager.onRecordAddEvent("charsheet", nodeChar);
		buildCharacter(nodeChar, nStartingLevel);
	else
		_creationPending = true;
		local tBuild = UtilityManager.copyDeep(S);
		UserManager.requestIdentity(nil, { fnResponse = function(result, identity)
			_creationPending = false;
			if not identity then return; end
			local nodeChar = DB.findNode(DB.getPath("charsheet", identity));
			if nodeChar then
				S = tBuild;
				buildCharacter(nodeChar, nStartingLevel);
			end
		end });
	end
end

function buildCharacter(nodeChar, nStartingLevel)
	local nLevel = nStartingLevel or getStartLevel();
	local nodeRace, nodeClass = getRaceNode(), getClassNode();

	DB.setValue(nodeChar, "name", "string", StringManager.trim(S.name));
	for _, s in ipairs(STATS) do
		DB.setValue(nodeChar, "attributes." .. s .. ".score", "number", S.scores[s] or 10);
		DB.setValue(nodeChar, "attributes." .. s .. ".prime", "number", 0);
	end

	-- Race first (its attribute modifiers land on the rolled scores), then class.
	local nodeRaceEntry = nil;
	if nodeRace then
		nodeRaceEntry = SiegeChar.addPackage(nodeChar, nodeRace, true);
		DB.setValue(nodeChar, "race", "string", DB.getValue(nodeRace, "name", ""));
	end
	local nodeClassEntry = nodeClass and SiegeChar.addPackage(nodeChar, nodeClass, true);
	for s, b in pairs(S.primes) do
		if b then
			DB.setValue(nodeChar, "attributes." .. s .. ".prime", "number", 1);
		end
	end
	for s in pairs(getForcedPrimes()) do
		DB.setValue(nodeChar, "attributes." .. s .. ".prime", "number", 1);
	end

	if nodeClassEntry then
		DB.setValue(nodeClassEntry, "level", "number", nLevel);
		DB.setValue(nodeClassEntry, "hproll", "number", countHP());
		if requiresManualProgression() and hasManualProgressionValues() then
			local nManualHP, nManualBtH = getManualProgressionValues();
			-- Store completed manual progression values only; unfinished values
			-- remain available for the CK to determine later. Store the
			-- CK decision on the copied package as an auditable explicit choice.
			DB.setValue(nodeClassEntry, "manualhp", "string", tostring(nManualHP));
			DB.setValue(nodeClassEntry, "manualbth", "number", nManualBtH);
		end
		for n, nGain in pairs(S.hp) do
			DB.setValue(nodeClassEntry, "hplog.l" .. n, "number", nGain);
		end
		-- Combined classes (Adventurer's Backpack), marked for CCCombine.
		local nodeMulti, nodeSupport = getMultiNode(), getSupportClassNode();
		if nodeMulti then
			CCCombine.addMulti(nodeChar, nodeClassEntry, nodeMulti, nLevel);
		elseif nodeSupport and S.combo.support then
			CCCombine.addSupport(nodeChar, nodeClassEntry, nodeSupport, S.combo.support, nLevel);
		end
		for _, nodePlus in ipairs(getPlusNodes()) do
			CCCombine.addPlus(nodeChar, nodePlus);
		end
		DB.setValue(nodeChar, "exp", "number", getStartXP(nLevel));
		SiegeChar.refreshPackages(nodeChar);
	end
	local nManualHP = requiresManualProgression() and select(1, getManualProgressionValues()) or nil;
	DB.setValue(nodeChar, "hp.total", "number", nManualHP or S.hptotal);
	DB.setValue(nodeChar, "hp.wounds", "number", 0);

	-- Equipment: the first armor, shield and helm bought are worn; weapons are equipped.
	local tWorn = {};
	for _, v in ipairs(S.cart) do
		for _ = 1, v.count do
			ItemManager.handleItem(nodeChar, nil, "item", v.path);
		end
	end
	for _, nodeItem in pairs(DB.getChildren(nodeChar, "inventorylist")) do
		local nAC = DB.getValue(nodeItem, "acbonus", 0);
		local sSlot = DB.getValue(nodeItem, "subtype", ""):lower();
		if DB.getValue(nodeItem, "type", "") == "Armor" and sSlot ~= "shield" and sSlot ~= "helm" then
			sSlot = "armor";
		end
		if nAC > 0 and (sSlot == "armor" or sSlot == "shield" or sSlot == "helm") and not tWorn[sSlot] then
			tWorn[sSlot] = true;
			DB.setValue(nodeItem, "carried", "number", 2);
		elseif DB.getValue(nodeItem, "damage", "") ~= "" and DB.getValue(nodeItem, "type", "") == "Weapon" then
			-- Weapons bought are ready (equipped), as on the official sheet.
			DB.setValue(nodeItem, "carried", "number", 2);
		end
	end
	local nLeft = getLeft();
	if nLeft > 0 then
		if math.floor(nLeft / 100) > 0 then CurrencyManager.addRecordCurrency(nodeChar, "gp", math.floor(nLeft / 100)); end
		if math.floor((nLeft % 100) / 10) > 0 then CurrencyManager.addRecordCurrency(nodeChar, "sp", math.floor((nLeft % 100) / 10)); end
		if nLeft % 10 > 0 then CurrencyManager.addRecordCurrency(nodeChar, "cp", nLeft % 10); end
	end

	-- Each spell at this class's level for it ("Cure Light Wounds" is level
	-- 1 for a cleric, 2 for a druid), so it spends the right slot.
	-- A combined character's spells are bound to their class's spell pool.
	local bTwo = hasSecondSpells();
	for _, tSet in ipairs({ { S.spells, getMainSpellClass() }, { S.spells2, getSecondSpellClass() } }) do
		for sPath in pairs(tSet[1]) do
			local nodePower = SiegePower.addPower(nodeChar, sPath);
			local nLevel = nodePower and getPowerLevelFor(DB.findNode(sPath), tSet[2]);
			if nLevel then
				DB.setValue(nodePower, "level", "number", nLevel);
				if bTwo then
					DB.setValue(nodePower, "spellpool", "string", SiegeChar.normalizeSpellPool(tSet[2]));
					DB.setValue(nodePower, "spelllevel", "number", nLevel);
				end
			end
		end
	end

	-- Languages the race's description names ("Languages: Common, Dwarven,
	-- ..."); a "choose N of the following" list is left to the player.
	if nodeRace then
		for _, sLang in ipairs(getRaceLanguages(nodeRace)) do
			local nodeLang = DB.createChild(DB.createChild(nodeChar, "languagelist"));
			DB.setValue(nodeLang, "name", "string", sLang);
		end
	end

	-- Details (Notes tab).
	for _, sField in ipairs({ "gender", "age", "height", "weight" }) do
		if (S[sField] or "") ~= "" then
			DB.setValue(nodeChar, sField, "string", S[sField]);
		end
	end
	if (S.appearance or "") ~= "" then
		DB.setValue(nodeChar, "appearance", "string", S.appearance);
	end
	-- Alignment and deity have their own fields (Notes tab: Alignment,
	-- Religion); the notes hold only the player's notes.
	local sNotes = S.notes or "";
	if S.unfinished and #S.unfinished > 0 then
		local sOpen = string.format(Interface.getString("ccwiz_notes_unfinished"), table.concat(S.unfinished, ", "));
		sNotes = sNotes ~= "" and (sOpen .. "\n\n" .. sNotes) or sOpen;
	end
	if sNotes ~= "" then
		DB.setValue(nodeChar, "notes", "string", sNotes);
	end
	if (S.alignment or "") ~= "" then
		DB.setValue(nodeChar, "alignment", "string", S.alignment);
	end
	if (S.deity or "") ~= "" then
		DB.setValue(nodeChar, "deity", "string", S.deity);
	end

	-- The same race and class summaries a sheet drop posts.
	if S.quiet then
		return;
	end
	if SiegeChar.postPackageSummary then
		SiegeChar.postPackageSummary(nodeChar, nodeRaceEntry);
		SiegeChar.postPackageSummary(nodeChar, nodeClassEntry);
	end
	ChatManager.SystemMessage(string.format(Interface.getString("ccwiz_msg_created"), StringManager.trim(S.name), nLevel,
		nodeRace and DB.getValue(nodeRace, "name", "") or "", nodeClass and DB.getValue(nodeClass, "name", "") or ""));
	if S.unfinished and #S.unfinished > 0 then
		ChatManager.SystemMessage(string.format(Interface.getString("ccwiz_msg_unfinished"), StringManager.trim(S.name),
			table.concat(S.unfinished, ", ")));
	end
	Interface.openWindow("charsheet", nodeChar);
	if _wMain then
		_wMain.close();
	end
end

function getRaceLanguages(nodeRace)
	local sText = plainText(DB.getValue(nodeRace, "text", ""));
	local sLine = sText:match("[Ll]anguages?:%s*([^\n]+)");
	local t = {};
	if not sLine then
		return t;
	end
	sLine = sLine:gsub("[%.;]%s*$", "");
	sLine = sLine:gsub(",?%s*and%s+%a+%s+of%s+the%s+following.*$", "");
	sLine = sLine:gsub("%s+and%s+", ", ");
	for sLang in sLine:gmatch("[^,]+") do
		sLang = StringManager.trim((sLang:gsub("^%s*and%s+", "")));
		if sLang ~= "" and #sLang < 30 then
			table.insert(t, sLang);
		end
	end
	return t;
end

function getStats()
	return STATS;
end

function getStatShort(s)
	return STAT_SHORT[s] or s;
end

-- Formatted text to plain paragraphs for a read-only text box.
function plainText(s)
	s = (s or ""):gsub("</p>%s*", "\n\n"):gsub("<br%s*/?>", "\n"):gsub("<li>", "  - "):gsub("</li>", "\n");
	s = s:gsub("<[^>]+>", "");
	s = s:gsub("&amp;", "&"):gsub("&lt;", "<"):gsub("&gt;", ">"):gsub("&quot;", "\""):gsub("&#8217;", "'"):gsub("&#8212;", "-"):gsub("&#8211;", "-");
	return StringManager.trim(s);
end

-- Sets a Finish-page detail (name, alignment, deity, ...) by key.
function setDetail(sKey, sValue)
	S[sKey] = sValue or "";
	refreshAll();
end

--
-- Pregenerated characters (cc-conversion/pregens): a build from a spec, run
-- through the Claude Bridge on the host. No window, no rolls, no chat.
--

-- Names compared in lower case, letters and digits only ("Rogue's Tools").
local function plainName(s)
	return ((s or ""):lower():gsub("[^%w]", ""));
end

local function findPackage(sType, sName)
	local sWant = plainName(sName);
	for _, node in ipairs(getPackages(sType)) do
		if plainName(DB.getValue(node, "name", "")) == sWant then
			return node;
		end
	end
	return nil;
end

local function findRecord(sRecordType, sName, fnAccept)
	local sWant = plainName(sName);
	local nodeFound = nil;
	RecordManager.callForEachRecord(sRecordType, function(node)
		if not nodeFound and plainName(DB.getValue(node, "name", "")) == sWant and (not fnAccept or fnAccept(node)) then
			nodeFound = node;
		end
	end);
	return nodeFound;
end

-- Spec: { name, race, class, level, scores = { strength = final score, ... },
--   primes = { "wisdom", ... } (chosen; the class prime is added),
--   alignment, deity, gender, age, height, weight, appearance, notes,
--   gold = coin in gp before buying, gear = { { "Sword, Long", 1 }, ... },
--   worn = { item names put on }, packed = { item names }, container = the
--   item they are packed in ("Backpack"),
--   spells = { "Bless", ... } (in order of preference; spells above the
--   level's reach or past its slots are skipped; slots left take the
--   class list in alphabetical order) }.
-- Hit points: 1st level the die's maximum, later levels the die's average
-- rounded up, plus the Constitution modifier (at least 1 a level).
-- Returns { path, hp, coinleft, problems, auto (spells picked for it),
-- skipped (spells out of reach or past the slots) }.
function buildFromSpec(tSpec)
	local tReport = { problems = {}, auto = {}, skipped = {} };
	local function problem(s) table.insert(tReport.problems, s); end
	reset();
	S.quiet = true;
	local nodeRace = findPackage("Race", tSpec.race);
	local nodeClass = findPackage("Class", tSpec.class);
	if not nodeRace then problem("race not found: " .. tostring(tSpec.race)); end
	if not nodeClass then problem("class not found: " .. tostring(tSpec.class)); return tReport; end
	S.race = nodeRace and DB.getPath(nodeRace) or nil;
	S.class = DB.getPath(nodeClass);
	S.startlevel = tonumber(tSpec.level) or 1;
	for _, s in ipairs(STATS) do
		local nFinal = tonumber((tSpec.scores or {})[s]) or 10;
		S.scores[s] = nFinal - getRaceMod(s);
	end
	local tForced = getForcedPrimes();
	for _, s in ipairs(tSpec.primes or {}) do
		if not tForced[s] then
			S.primes[s] = true;
		end
	end
	local nChosen, nAllowed = getPrimeCounts();
	if nChosen ~= nAllowed then
		problem(string.format("primes: %d chosen, %d allowed", nChosen, nAllowed));
	end

	-- Hit points.
	S.hp, S.hptotal = {}, 0;
	local nCon = getConMod();
	for _, r in ipairs(getHPPlan()) do
		local nGain = r.flat;
		if #r.dice > 0 then
			for _, d in ipairs(r.dice) do
				local nDie = tonumber(d:match("d(%d+)")) or 0;
				nGain = nGain + (r.level == 1 and nDie or (math.floor(nDie / 2) + 1));
			end
			nGain = math.max(1, nGain + nCon);
		end
		S.hp[r.level] = nGain;
		S.hptotal = S.hptotal + nGain;
	end
	S.hpsignature = getHPSignature();

	-- Coin and gear.
	S.gold = tonumber(tSpec.gold) or 0;
	for _, v in ipairs(tSpec.gear or {}) do
		-- An item with a plain price (another book's "Club" may have none),
		-- the Player's Handbook's first, as in the shop (its load fields:
		-- the Backpack prints no worn mark on armor or packs).
		local function priced(node) return parseCost(DB.getValue(node, "cost", "")) ~= nil; end
		local nodeItem = findRecord("item", v[1], function(node) return priced(node) and isCore(node); end)
			or findRecord("item", v[1], priced);
		if not nodeItem then
			problem("item not found: " .. tostring(v[1]));
		else
			for _ = 1, (tonumber(v[2]) or 1) do
				local nBefore = getSpent();
				buy(nodeItem);
				if getSpent() == nBefore then
					problem("cannot buy: " .. tostring(v[1]));
					break;
				end
			end
		end
	end

	-- Spells: the spec's first, then the class list for slots left.
	local tDay = getSpellPicksAllowed();
	if next(tDay) then
		local tByName = {};
		for _, t in ipairs(getSpellChoices("")) do
			tByName[plainName(DB.getValue(t.node, "name", ""))] = t;
		end
		for _, sName in ipairs(tSpec.spells or {}) do
			local t = tByName[plainName(sName)];
			if not t then
				table.insert(tReport.skipped, sName);
			elseif countSpellsAt(t.level) < (tDay[t.level] or 0) then
				S.spells[DB.getPath(t.node)] = t.level;
			else
				table.insert(tReport.skipped, sName);
			end
		end
		for _, t in ipairs(getSpellChoices("")) do
			local sPath = DB.getPath(t.node);
			if not S.spells[sPath] and countSpellsAt(t.level) < (tDay[t.level] or 0) then
				S.spells[sPath] = t.level;
				table.insert(tReport.auto, DB.getValue(t.node, "name", ""));
			end
		end
	end

	for _, sField in ipairs({ "name", "alignment", "deity", "gender", "age", "height", "weight", "appearance", "notes" }) do
		S[sField] = tSpec[sField] or "";
	end
	local nodeChar = DB.createChild("charsheet");
	DB.setValue(nodeChar, "name", "string", StringManager.trim(S.name));
	buildCharacter(nodeChar, S.startlevel);
	-- Worn clothing and pack, and small gear packed in the pack (load).
	local tWorn, tPacked = {}, {};
	for _, s in ipairs(tSpec.worn or {}) do tWorn[plainName(s)] = true; end
	for _, s in ipairs(tSpec.packed or {}) do tPacked[plainName(s)] = true; end
	local sContainer = nil;
	for _, nodeItem in ipairs(DB.getChildList(nodeChar, "inventorylist")) do
		local sName = plainName(DB.getValue(nodeItem, "name", ""));
		if sName == plainName(tSpec.container) then sContainer = DB.getValue(nodeItem, "name", ""); end
	end
	for _, nodeItem in ipairs(DB.getChildList(nodeChar, "inventorylist")) do
		local sName = plainName(DB.getValue(nodeItem, "name", ""));
		if tWorn[sName] then
			DB.setValue(nodeItem, "carried", "number", 2);
		elseif tPacked[sName] and sContainer then
			DB.setValue(nodeItem, "location", "string", sContainer);
		end
	end
	tReport.path = DB.getPath(nodeChar);
	tReport.hp = S.hptotal;
	tReport.coinleft = getLeft();
	reset();
	return tReport;
end

