local originalReset = reset;
function reset()
 prepareOfficialRecords();
 originalReset();
end
function forEachOfficial(kind, fn)
 for _, node in pairs(DB.getChildren("ccwizardofficial." .. kind)) do fn(node); end
end
-- Classes and races come from every loaded book, as the 2E wizard does
-- (Discord, 2026-10-19: the Adventurer's Backpack classes were missing).
-- A Players Handbook class or race uses OFFICIAL_METADATA. Any other class is
-- read from its own record: hit die, prime and the Advancement table (level,
-- HD, BtH, XP and spells per day). A variant like "Ranger (Spell Caster)"
-- starts from the base class's metadata. OFFICIAL_BOOK_EXTRAS adds what a
-- book's table does not hold (spell list, bonus spells, starting gold).
local function findMetadata(tData, name, exact)
 local want = (exact and name or name:gsub(" %(.*%)", "")):lower();
 for key, value in pairs(tData) do if key:lower() == want then return value; end end
 return nil;
end
local function applyMetadata(node, metadata)
 for field, value in pairs(metadata or {}) do
  local old = DB.getChild(node, field); if old then DB.deleteNode(old); end
  DB.setValue(node, field, value[1], value[2]);
 end
end
local function setField(node, field, sType, value)
 local old = DB.getChild(node, field); if old then DB.deleteNode(old); end
 DB.setValue(node, field, sType, value);
end
local function tableCells(sRow)
 local t = {};
 for sCell in sRow:gmatch("<td[^>]*>(.-)</td>") do
  table.insert(t, StringManager.trim((sCell:gsub("<[^>]+>", ""):gsub("&nbsp;", " "))));
 end
 return t;
end
local function toNumber(s)
 return tonumber(((s or ""):gsub("[^%d%-]", "")));
end
-- The Advancement table of a class record: true when it gave level rows.
local function readAdvancement(source, node)
 local sText = DB.getValue(source, "text");
 if type(sText) ~= "string" then return false; end
 for sTable in sText:gmatch("<table[^>]*>(.-)</table>") do
  local rows = {};
  for sRow in sTable:gmatch("<tr[^>]*>(.-)</tr>") do table.insert(rows, tableCells(sRow)); end
  local nHD, nBtH, nXP, nSlots;
  for _, row in ipairs(rows) do
   if (row[1] or ""):lower() == "level" then
    for i, s in ipairs(row) do
     s = s:lower();
     if s == "hd" then nHD = i; elseif s == "bth" then nBtH = i;
     elseif s == "epp" or s == "xp" or s == "exp" then nXP = i;
     elseif s:find("spells") then nSlots = i; end
    end
    break;
   end
  end
  -- No heading row (the Spell Caster paladin): level, XP, spells per day.
  if not nXP and #rows > 0 and (rows[1][1] or ""):match("^%d+$") then
   nXP = 2; nSlots = 3;
  end
  local tLevels, nLast, nLastXP = {}, 0, 0;
  local nDice, sDie, nFlat, nStep = 0, "", 0, nil;
  local nFrom, nRate;
  for _, row in ipairs(rows) do
   local sLevel = row[1] or "";
   if sLevel:match("^%d+$") and nXP and row[nXP] then
    local n = tonumber(sLevel);
    local tRow = { xp = toNumber(row[nXP]) or 0 };
    if nBtH and row[nBtH] then tRow.bth = toNumber(row[nBtH]) or 0; end
    if nHD and row[nHD] then
     local s = row[nHD]:lower();
     local sD = s:match("^1?(d%d+)$");
     if sD then
      nDice = nDice + 1; sDie = sD;
     else
      -- "+4 HP" a level after the last hit die (a misprint like "15" repeats the last step).
      local nAdd = tonumber(s:match("^%+?%s*(%d+)") or "");
      if nAdd and nAdd <= 10 then nStep = nAdd; end
      if nStep then nFlat = nFlat + nStep; end
     end
     if nDice > 0 then tRow.hd = nDice .. sDie .. (nFlat > 0 and ("+" .. nFlat) or ""); end
    end
    if nSlots then
     local t = {};
     for i = nSlots, #row do if row[i] ~= "" then table.insert(t, toNumber(row[i]) or 0); end end
     if #t > 0 then tRow.slots = table.concat(t, ","); end
    end
    tLevels[n] = tRow; nLast = math.max(nLast, n); nLastXP = tRow.xp;
   elseif sLevel:match("^%d+%+$") then
    nFrom = tonumber(sLevel:match("%d+"));
    nRate = toNumber((row[2] or ""):match("[%d,]+"));
   end
  end
  if tLevels[1] then
   for n, tRow in pairs(tLevels) do
    local sPath = string.format("levels.l%02d.", n);
    DB.setValue(node, sPath .. "level", "number", n);
    DB.setValue(node, sPath .. "xp", "number", tRow.xp);
    if tRow.bth then DB.setValue(node, sPath .. "bth", "number", tRow.bth); end
    if tRow.hd then DB.setValue(node, sPath .. "hd", "string", tRow.hd); end
    if tRow.slots then DB.setValue(node, sPath .. "slots", "string", tRow.slots); end
   end
   -- "13+: +200,000 per level": XP to 24th level; HP and BtH are the CK's.
   if nFrom and nRate and nFrom == nLast + 1 then
    for n = nFrom, 24 do
     local sPath = string.format("levels.l%02d.", n);
     DB.setValue(node, sPath .. "level", "number", n);
     DB.setValue(node, sPath .. "xp", "number", nLastXP + nRate * (n - nLast));
     DB.setValue(node, sPath .. "bth", "number", 0);
     DB.setValue(node, sPath .. "hd", "string", "");
    end
    setField(node, "manualprogression", "number", 1);
    setField(node, "manualfromlevel", "number", nFrom);
    setField(node, "manualbth", "number", tLevels[nLast].bth or 0);
    setField(node, "xpcontinuationfrom", "number", nFrom);
    setField(node, "xpcontinuationbase", "number", nLastXP);
    setField(node, "xpcontinuationrate", "number", nRate);
   end
   if sDie ~= "" then setField(node, "hitdie", "string", sDie); end
   return true;
  end
 end
 return false;
end
local function readClass(source, node, name, tSpellLists)
 local base = findMetadata(OFFICIAL_METADATA, name, false);
 if base then
  applyMetadata(node, base);
 else
  setField(node, "ccgen", "number", 1);
  setField(node, "packagetype", "string", "Class");
  setField(node, "primechoice", "number", 0);
 end
 -- The hit die is text ("d8") or a dice field ({"d8"}).
 local vDie = DB.getValue(source, "hitdie");
 if type(vDie) == "table" then vDie = vDie[1]; end
 local sDie = type(vDie) == "string" and vDie:lower():match("(d%d+)") or nil;
 if sDie then setField(node, "hitdie", "string", sDie); elseif not base then setField(node, "hitdie", "string", ""); end
 if not readAdvancement(source, node) and not base then return false; end
 local sPrime = DB.getValue(source, "primeattribute");
 sPrime = type(sPrime) == "string" and sPrime:lower() or "";
 if not base and sPrime ~= "" then
  for _, s in ipairs({ "strength", "dexterity", "constitution", "intelligence", "wisdom", "charisma" }) do
   if sPrime:find(s, 1, true) then DB.setValue(node, "primes." .. s, "number", 1); end
  end
 end
 applyMetadata(node, findMetadata(OFFICIAL_BOOK_EXTRAS, name, true));
 -- A class of another book that casts from a spell list named for it.
 if DB.getValue(node, "spellclass", "") == "" and tSpellLists[name:lower()] then
  setField(node, "spellclass", "string", tSpellLists[name:lower()]);
 end
 return DB.getChild(node, "levels.l01") ~= nil;
end
local function readRace(source, node)
 setField(node, "ccgen", "number", 1);
 setField(node, "packagetype", "string", "Race");
 setField(node, "primechoice", "number", 1);
 local vSpeed = DB.getValue(source, "speed");
 if type(vSpeed) == "number" then vSpeed = vSpeed > 0 and (vSpeed .. " ft.") or ""; end
 setField(node, "speed", "string", type(vSpeed) == "string" and vSpeed or "");
end
function prepareOfficialRecords()
 if not Session.IsHost then return; end
 local previous=DB.findNode("ccwizardofficial");if previous then DB.deleteNode(previous);end
 local root = DB.createNode("ccwizardofficial");
 -- The spell lists of the loaded books ("Druid 1, Cleric 2" gives Druid, Cleric).
 local tSpellLists = {};
 RecordManager.callForEachRecord("spell", function(source)
  for sList in DB.getValue(source, "level", ""):gmatch("([^,%d]+)%d") do
   sList = StringManager.trim(sList);
   if sList ~= "" then tSpellLists[sList:lower()] = sList; end
  end
 end);
 local function populate(recordType, kind)
  RecordManager.callForEachRecord(recordType, function(source)
   local name = DB.getValue(source, "name", "");
   if (kind == "races" or kind == "classes") and name == "" then return; end
   local key = DB.getPath(source):gsub("[^%w]", "_");
   local node = DB.createNode("ccwizardofficial." .. kind .. "." .. key);
   DB.copyNode(source, node);
   DB.setValue(node, "officialpath", "string", DB.getPath(source));
   if kind == "classes" then
    local metadata = findMetadata(OFFICIAL_METADATA, name, true);
    if metadata then applyMetadata(node, metadata);
    elseif not readClass(source, node, name, tSpellLists) then DB.deleteNode(node); return; end
   elseif kind == "races" then
    local metadata = findMetadata(OFFICIAL_METADATA, name, false);
    if metadata then applyMetadata(node, metadata); else readRace(source, node); end
    local traits=DB.getChild(source,"traits");if traits then DB.copyNode(traits,DB.createChild(node,"abilities"));end
   elseif kind == "items" then
    DB.setValue(node, "cost", "string", DB.getValue(source, "value", ""));
    DB.setValue(node, "type", "string", DB.getValue(source, "itemtype", ""));
   elseif kind == "spells" then
    DB.setValue(node, "powertype", "string", DB.getValue(source, "level", ""));
    DB.setValue(node, "text", "formattedtext", DB.getValue(source, "description", ""));
   end
  end);
 end
 populate("race", "races"); populate("class", "classes"); populate("item", "items"); populate("spell", "spells");
 DB.setPublic(root, true);
end
function getPackages(kind)
 local out = {};
 forEachOfficial(kind == "Race" and "races" or "classes", function(node)
  if Session.IsHost or not isBlocked(DB.getValue(node, "name", "")) then table.insert(out, node); end
 end);
 table.sort(out, function(a,b) return DB.getValue(a,"name","") < DB.getValue(b,"name",""); end);
 return out;
end
function getOfficialHPGain(node, level)
 local function parse(n)
  local row = getLevelRow(node,n);
  local dice, flat = DiceManager.convertStringToDice(n > 0 and row and DB.getValue(row,"hd","") or "",true);
  local counts = {};
  for _, d in ipairs(dice or {}) do local key = type(d)=="table" and d.type or d; counts[key]=(counts[key] or 0)+1; end
  return counts,flat or 0;
 end
 local now,flat = parse(level); local before,prev = parse(level-1); local dice={};
 for d,count in pairs(now) do for i=1,count-(before[d] or 0) do table.insert(dice,d); end end
 return dice,math.max(0,flat-prev);
end
-- Spells per day at the starting level, for the list shown (the class's, or
-- a combined character's second list: a multi-class caster's, or a
-- spell-casting supporting class's Supporting Spells table).
function getOfficialSlots(node, nLevel)
 local row=node and getLevelRow(node,nLevel); local result={};local index=0;
 for count in (row and DB.getValue(row,"slots","") or ""):gmatch("[^,]+") do result[index]=tonumber(count) or 0;index=index+1;end
 local stat=node and DB.getValue(node,"slotbonusstat","") or "";
 local score=stat~="" and (getFinalScore(stat) or 10) or 10;
 for threshold,level,count in (node and DB.getValue(node,"slotbonuses","") or ""):gmatch("(%d+):(%d+):(%d+)") do
  level=tonumber(level);if score>=tonumber(threshold) and (result[level] or 0)>0 then result[level]=result[level]+tonumber(count);end
 end
 return result;
end
function getSpellsPerDay()
 if getSpellSet()=="second" then
  if S.combo.support then return CCClassRules.getSupportSlots(S.combo.support,getStartLevel()) or {}; end
  return getOfficialSlots(getMultiNode(),getStartLevel());
 end
 return getOfficialSlots(getClassNode(),getStartLevel());
end
-- The book a proxy record comes from (its official record's module).
function getSourceName(node)
 local sModule=(DB.getValue(node,"officialpath",""):match("@(.+)$")) or DB.getModule(node) or "";
 if sModule=="" then return "Campaign"; end
 local tInfo=Module.getModuleInfo(sModule);
 return (tInfo and tInfo.displayname~="" and tInfo.displayname) or sModule;
end
-- Opens the official race or class record for reading.
function openRecord(sPath)
 local node=DB.findNode(sPath);
 local sOfficial=DB.getValue(node,"officialpath","");
 local sClass=sOfficial:find("^reference%.races") and "referencerace" or "referenceclass";
 Interface.openWindow(sClass,sOfficial~="" and sOfficial or sPath);
end
local function shortcut(class,path)
 return {getType=function()return "shortcut";end,isType=function(t)return t=="shortcut";end,getShortcutData=function()return class,path;end,getDatabaseNode=function()return DB.findNode(path);end};
end

--
-- Combined classes on the official sheet (Adventurer's Backpack). The sheet
-- holds one class (classes.slot1); a multi-class second class or an enhanced
-- class's supporting class is classes.slot2 (name, level, kind "multi" or
-- "enhanced", key, officialpath); class plus is ccplus.<key> (name, text).
-- Their abilities are rows on the ability list (source = the class).
--

function findOfficialProxy(sName)
 local sKey=CCClassRules.key(sName);local found=nil;
 forEachOfficial("classes",function(node) if CCClassRules.key(DB.getValue(node,"name",""))==sKey then found=node;end end);
 return found;
end
function getOfficialLevelXP(node,nLevel)
 local row=node and getExactLevelRow(node,nLevel);
 return row and DB.getValue(row,"xp",0) or 0;
end
-- XP needed for the next level of a combined official character, or nil.
function getOfficialNextXP(nodeChar)
 local sMain=DB.getValue(nodeChar,"classes.slot1.name","");
 local nLevel=DB.getValue(nodeChar,"classes.slot1.level",0)+1;
 local nodeMain=findOfficialProxy(sMain);
 local sKind=DB.getValue(nodeChar,"classes.slot2.kind","");
 local nPlus=DB.getChildCount(nodeChar,"ccplus");
 if not nodeMain or (sKind~="multi" and sKind~="enhanced" and sKind~="dual" and sKind~="reclass" and nPlus==0) then return nil; end
 -- Dual class and reclass count from the XP held at the switch (classes.slot2.xpbase):
 -- a reclassed character's experience all goes to the new class; a dual-classed
 -- one's is split equally, the original class keeping what it had.
 if sKind=="dual" or sKind=="reclass" then
  local nBase=DB.getValue(nodeChar,"classes.slot2.xpbase",0);
  local proxy2=findOfficialProxy(DB.getValue(nodeChar,"classes.slot2.name",""));
  local nNeed2=proxy2 and getOfficialLevelXP(proxy2,DB.getValue(nodeChar,"classes.slot2.level",1)+1) or 0;
  if sKind=="reclass" then return nNeed2>0 and nBase+nNeed2 or nil; end
  local nNeed1=getOfficialLevelXP(nodeMain,nLevel);
  local nNext;
  if nNeed1>0 then nNext=nBase+2*math.max(nNeed1-nBase,0); end
  if nNeed2>0 and (not nNext or nBase+2*nNeed2<nNext) then nNext=nBase+2*nNeed2; end
  return nNext;
 end
 local nNext=getOfficialLevelXP(nodeMain,nLevel);
 if sKind=="multi" then
  nNext=nNext+getOfficialLevelXP(findOfficialProxy(DB.getValue(nodeChar,"classes.slot2.name","")),nLevel);
 elseif sKind=="enhanced" then
  nNext=nNext+CCClassRules.getSupportXP(DB.getValue(nodeChar,"classes.slot2.key",""),nLevel);
 end
 return CCClassRules.getPlusXP(nNext,nPlus);
end
function setOfficialXPNeeded(nodeChar)
 local n=getOfficialNextXP(nodeChar);
 if n then DB.setValue(nodeChar,"expneeded","number",n); end
end
-- A combined class's abilities on the ability list, levels nFrom..nTo; a
-- sub-class keeps only its own (sKey).
function addOfficialAbilities(nodeChar,proxy,nFrom,nTo,sSource,sKey)
 for _,v in pairs(DB.getChildren(proxy,"abilities")) do
  local n=tonumber(DB.getValue(v,"level",""))or 1;
  local sName=DB.getValue(v,"name","");
  if n>=nFrom and n<=nTo and (not sKey or CCClassRules.isSupportAbility(sKey,sName)) then
   local row=DB.createChild(DB.createChild(nodeChar,"abilitylist"));
   DB.setValue(row,"name","string",sName);DB.setValue(row,"type","string","Class Ability");
   DB.setValue(row,"source","string",sSource);DB.setValue(row,"level","number",n);
   DB.setValue(row,"text","formattedtext",DB.getValue(v,"text",""));DB.setValue(row,"locked","number",1);
  end
 end
end
-- The spell block of a class (spellset.<id> with spellclass.name), made when missing.
function getOfficialSpellBlock(nodeChar,sClass,bCreate)
 for _,n in pairs(DB.getChildren(nodeChar,"spellset")) do
  if DB.getValue(n,"spellclass.name",""):lower()==sClass:lower() then return n; end
 end
 if not bCreate then return nil; end
 local n=DB.createChild(DB.createChild(nodeChar,"spellset"));
 DB.setValue(n,"spellclass.name","string",sClass);DB.setValue(n,"caster_level","number",0);
 return n;
end
function addOfficialSpells(block,tSlots,tPicks)
 for n,count in pairs(tSlots) do DB.setValue(block,"spellsavailable.availablelevel"..n,"number",count);end
 for path,n in pairs(tPicks) do
  local source=DB.getValue(path..".officialpath","");local dest=DB.createChild(DB.createChild(block,"levels.level"..n..".spells"));
  DB.copyNode(DB.findNode(source),dest);DB.setValue(dest,"prepared","number",1);DB.setValue(dest,"cast","number",0);DB.setValue(dest,"shortcut","windowreference","spell",source);
 end
end
function addOfficialCombos(nodeChar,level)
 local nodeMulti,nodeSupport=getMultiNode(),getSupportClassNode();
 local sSecond="";
 if nodeMulti then
  sSecond=DB.getValue(nodeMulti,"name","");
  DB.setValue(nodeChar,"classes.slot2.name","string",sSecond);DB.setValue(nodeChar,"classes.slot2.level","number",level);
  DB.setValue(nodeChar,"classes.slot2.kind","string","multi");DB.setValue(nodeChar,"classes.slot2.officialpath","string",DB.getValue(nodeMulti,"officialpath",""));
  addOfficialAbilities(nodeChar,nodeMulti,1,level,sSecond,nil);
  local rowMain=getLevelRow(getClassNode(),level);local rowSecond=getLevelRow(nodeMulti,level);
  DB.setValue(nodeChar,"attackbonus.base","number",math.max(rowMain and DB.getValue(rowMain,"bth",0) or 0,rowSecond and DB.getValue(rowSecond,"bth",0) or 0));
 elseif nodeSupport and S.combo.support then
  local tSupport=CCClassRules.getSupport(S.combo.support);
  sSecond=DB.getValue(nodeSupport,"name","");
  local nLevel=CCClassRules.getSupportLevel(S.combo.support,level);
  DB.setValue(nodeChar,"classes.slot2.name","string",tSupport.sub and (tSupport.name.." ("..sSecond..")") or tSupport.name);
  DB.setValue(nodeChar,"classes.slot2.level","number",nLevel);DB.setValue(nodeChar,"classes.slot2.kind","string","enhanced");
  DB.setValue(nodeChar,"classes.slot2.key","string",S.combo.support);DB.setValue(nodeChar,"classes.slot2.officialpath","string",DB.getValue(nodeSupport,"officialpath",""));
  addOfficialAbilities(nodeChar,nodeSupport,1,nLevel,sSecond,S.combo.support);
 end
 for _,node in ipairs(getPlusNodes()) do
  local sName=DB.getValue(node,"name","");local sKey=CCClassRules.key(sName);local sText=CCClassRules.getPlusText(sName) or "";
  DB.setValue(nodeChar,"ccplus."..sKey..".name","string",sName);DB.setValue(nodeChar,"ccplus."..sKey..".text","string",sText);
  local sLower=sText:lower();
  for _,v in pairs(DB.getChildren(node,"abilities")) do
   local sAbility=DB.getValue(v,"name","");local sWord=StringManager.trim(sAbility:lower():gsub("%s*%b()",""));
   if (tonumber(DB.getValue(v,"level",""))or 1)<=1 and sWord~="" and sLower:find(sWord,1,true) then
    local row=DB.createChild(DB.createChild(nodeChar,"abilitylist"));
    DB.setValue(row,"name","string",sAbility.." (class plus, 0 level)");DB.setValue(row,"type","string","Class Ability");
    DB.setValue(row,"source","string",sName.." (class plus)");DB.setValue(row,"level","number",0);
    DB.setValue(row,"text","formattedtext",DB.getValue(v,"text",""));DB.setValue(row,"locked","number",1);
   end
  end
  local row=DB.createChild(DB.createChild(nodeChar,"abilitylist"));
  DB.setValue(row,"name","string","Class Plus: "..sName);DB.setValue(row,"type","string","Class Ability");
  DB.setValue(row,"source","string",sName.." (class plus)");DB.setValue(row,"level","number",0);DB.setValue(row,"locked","number",1);
  DB.setValue(row,"text","formattedtext","<p>"..sText..". These abilities never improve past zero level; the character's level is not added to their checks. Each plussed class costs 5% of all experience earned (Adventurer's Backpack).</p>");
  local sCaster=sLower:match("two 0 level ([%a ]-) spells per day");
  if sCaster then
   local block=getOfficialSpellBlock(nodeChar,StringManager.capitalize(sCaster),true);
   DB.setValue(block,"spellsavailable.availablelevel0","number",math.max(2,DB.getValue(block,"spellsavailable.availablelevel0",0)));
  end
 end
 -- The second spell list.
 if hasSecondSpells() then
  local sSet=S.spellset;S.spellset="second";
  local block=getOfficialSpellBlock(nodeChar,getSecondSpellClass(),true);
  DB.setValue(block,"caster_level","number",DB.getValue(nodeChar,"classes.slot2.level",level));
  addOfficialSpells(block,getSpellsPerDay(),S.spells2);
  S.spellset=sSet;
 end
end

-- A class the official Character Builder cannot read (an Advancement table
-- without HD and BtH columns, like the Backpack's Spell Caster ranger, paladin
-- and bard: it says "No Advancement Table Detected" and opens no level window):
-- the wizard sets what the builder would have, the level, base to hit, the
-- class abilities of levels nFrom..nTo and the caster level.
function setLevelWithoutLoader(nodeChar,proxy,nFrom,nTo)
 local sName=DB.getValue(proxy,"name","");
 DB.setValue(nodeChar,"classes.slot1.name","string",sName);
 DB.setValue(nodeChar,"classes.slot1.level","number",nTo);
 -- Base to hit never drops (past the printed levels the row holds none).
 local row=getLevelRow(proxy,nTo);
 if row then DB.setValue(nodeChar,"attackbonus.base","number",math.max(DB.getValue(nodeChar,"attackbonus.base",0),DB.getValue(row,"bth",0)));end
 addOfficialAbilities(nodeChar,proxy,nFrom,nTo,sName,nil);
 local nextRow=getExactLevelRow(proxy,nTo+1);
 if nextRow then DB.setValue(nodeChar,"expneeded","number",DB.getValue(nextRow,"xp",0));end
 for _,n in pairs(DB.getChildren(nodeChar,"spellset")) do
  if DB.getValue(n,"spellclass.name","")==sName or DB.getValue(n,"spellclass.name","")==DB.getValue(proxy,"spellclass","") then DB.setValue(n,"caster_level","number",nTo);end
 end
end

function buildCharacter(nodeChar, level)
 level=level or getStartLevel();
 for _,stat in ipairs(STATS) do DB.setValue(nodeChar,"abilities."..stat..".score","number",S.scores[stat] or 10);end
 local w=Interface.openWindow("charsheet",nodeChar);
 local race,class=getRaceNode(),getClassNode();
 if race then w.onDrop(0,0,shortcut("referencerace",DB.getValue(race,"officialpath","")));end
 if class then
  w.onDrop(0,0,shortcut("referenceclass",DB.getValue(class,"officialpath","")));
  local popup=Interface.findWindow("class_drop_popup",DB.getPath(nodeChar,"popup"));
  if popup then
   popup.content.subwindow.new_level.setValue(tostring(level));
   -- The wizard's own hit points are written below; the loader must not roll more.
   if popup.roll_hp then popup.roll_hp.setValue("no_roll");end
   popup.accept.onButtonPress();
   -- Its level list holds only the printed rows (the Backpack prints 1-12 and
   -- "13+"): a level past them is not set, so the wizard sets it.
   if DB.getValue(nodeChar,"classes.slot1.level",0)~=level then
    popup=Interface.findWindow("class_drop_popup",DB.getPath(nodeChar,"popup"));
    if popup then popup.close();end
    setLevelWithoutLoader(nodeChar,class,1,level);
   end
  else
   setLevelWithoutLoader(nodeChar,class,1,level);
  end
 end
 for stat,prime in pairs(S.primes) do DB.setValue(nodeChar,"abilities."..stat..".prime","number",prime and 1 or 0);end
 for stat in pairs(getForcedPrimes()) do DB.setValue(nodeChar,"abilities."..stat..".prime","number",1);end
 -- Rolled hit points, or past the printed levels the Castle Keeper's total and BtH.
 DB.setValue(nodeChar,"hp.total","number",getSelectedHPTotal());
 local _,nManualBtH=getManualProgressionValues();
 if nManualBtH then DB.setValue(nodeChar,"attackbonus.base","number",nManualBtH);end
 if class then
  for n,gain in pairs(S.hp) do DB.setValue(nodeChar,"classes.slot1.hplog.l"..n,"number",gain);end
  DB.setValue(nodeChar,"classes.slot1.hplogclass","string",DB.getValue(class,"name",""));
  addOfficialCombos(nodeChar,level);
 end
 DB.setValue(nodeChar,"exp","number",getStartXP(level));
 setOfficialXPNeeded(nodeChar);
 w.tabs.activateTab(4);
 for _,item in ipairs(S.cart) do
  local proxy=DB.findNode(item.path);local source=DB.getValue(proxy,"officialpath","");
  local kind=DB.getValue(proxy,"itemtype","");local display=kind=="weapon" and "referenceweapon" or (kind=="armor" and "referencearmor" or "referenceequipment");
  for i=1,item.count do w.inventory.subwindow.inventorylist.onDrop(0,0,shortcut(display,source));end
 end
 local worn={};
 for _,item in pairs(DB.getChildren(nodeChar,"inventorylist")) do
  local kind=DB.getValue(item,"itemtype",""); local name=DB.getValue(item,"name",""):lower();
  if kind=="armor" then local slot=name:find("shield",1,true) and "shield" or "armor"; if not worn[slot] then DB.setValue(item,"carried","number",2);worn[slot]=true;end end
 end
 local money=math.max(0,getLeft());CurrencyManager.addRecordCurrency(nodeChar,"GP",math.floor(money/100));CurrencyManager.addRecordCurrency(nodeChar,"SP",math.floor(money%100/10));CurrencyManager.addRecordCurrency(nodeChar,"CP",money%10);
 if class and getMainSpellClass()~="" then
  w.tabs.activateTab(5);
  local block=getOfficialSpellBlock(nodeChar,getMainSpellClass(),false);
  if not block then for _,n in pairs(DB.getChildren(nodeChar,"spellset")) do block=n;break;end end
  -- A class the official loader made no spell block for (the Backpack's rune mark).
  if not block then block=getOfficialSpellBlock(nodeChar,getMainSpellClass(),true);DB.setValue(block,"caster_level","number",level);end
  if block then
   local sSet=S.spellset;S.spellset="main";
   addOfficialSpells(block,getSpellsPerDay(),S.spells);
   S.spellset=sSet;
  end
 end
 for _,field in ipairs({"name","alignment","gender","age","height","weight","appearance","notes"}) do DB.setValue(nodeChar,field,"string",S[field] or "");end
 -- An unfinished character (Create is always available): the open choices
 -- head the notes, to finish with the Castle Keeper.
 if S.unfinished and #S.unfinished>0 then
  local sOpen=string.format(Interface.getString("ccwiz_notes_unfinished"),table.concat(S.unfinished,", "));
  DB.setValue(nodeChar,"notes","string",(S.notes or "")~="" and (sOpen..string.char(10,10)..S.notes) or sOpen);
 end
 DB.setValue(nodeChar,"religion","string",S.deity or "");
 if race then
  for _,lang in ipairs(getRaceLanguages(race)) do local n=DB.createChild(DB.createChild(nodeChar,"languagelist"));DB.setValue(n,"name","string",lang);end
  for _,ability in pairs(DB.getChildren(nodeChar,"abilitylist")) do
   local name=DB.getValue(ability,"name","");local text=DB.getValue(ability,"text","");
   if name:lower():find("vision",1,true) then local distance=text:match("(%d+) feet");if distance then DB.setValue(nodeChar,"senses","string",name.." "..distance.." ft");end end
  end
 end
 w.tabs.activateTab(1);
 ChatManager.SystemMessage("Created "..(S.name or "").." using the official C&C character loader.");
 if S.unfinished and #S.unfinished>0 then
  ChatManager.SystemMessage(string.format(Interface.getString("ccwiz_msg_unfinished"),StringManager.trim(S.name or ""),table.concat(S.unfinished,", ")));
 end
 if _wMain then _wMain.close();end
end
